COLLDATA("musnadshafiiur","ur",[[709,"عبداللہ بن دینار رضی اللہ عنہ سے روایت ہے کہتے ہیں میں نے سعید بن مسیب رضی اللہ عنہ سے غیر عربی گھوڑوں کی زکوة کے متعلق پوچھا تو انہوں نے کہا: کیا گھوڑوں پر زکوة واجب ہے؟ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/119)، المعرفة السنن والآثار لہ (2298)، ابن ابی شیبة (10145، 10146)۔","f":"’’البراذین‘‘ اس سے مراد بار براداری کے لیے مضبوط غیر عربی گھوڑے ہیں۔ جس طرح عام گھوڑوں پر زکوة نہیں اسی طرح ان پر بھی زکوة فرض نہیں ہے۔"}],[710,"ابو عمرو بن حماس سے روایت ہے اس کے باپ نے کہا میں عمر بن خطاب رضی اللہ عنہ کے پاس سے گزرا جبکہ میں اپنی گردن پر چمڑا رکھے ہوئے تھا تو عمر رضی اللہ عنہ نے فرمایا، کیا تم اپنے مال کی زکوة نہیں دیتے اے حماس؟ حماس کہتے ہیں میں نے کہا، میرے پاس اس جمع کیے ہوئے چمڑے کے تھیلے کے علاوہ جو میری پیٹھ پر ہے کچھ نہیں۔ آپ نے فرمایا: یہ مال ہے، نیچے رکھو۔ حماس کہتے ہیں: میں نے ان کے سامنے اسے رکھ دیا، انہوں نے اس کا حساب لگایا تو مجھے پتہ چلا کہ اس پر زکوة واجب ہے، پھر انہوں نے اس سے زکوة لے لی۔ (1)","",{"k":"(1) اسنادة ضعیف، فان ابا عمرو بن حماس اللیثی مقبول حیث یتابع ولم یتابع: البیہقی (4/147)، المعرفة السنن والآثار لہ (2365، 2366)۔"}],[711,"ایک دوسری سند سے ابو عمرو بن حماس اپنے باپ سے اسی طرح بیان کرتے ہیں۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (710)۔"}],[712,"زریق بن حکیم سے روایت ہے کہ عمر بن عبدالعزیز رضی اللہ عنہ نے ان کی طرف (خط) لکھا کہ جو بھی مسلمانوں کا تجارتی سامان آپ کے پاس سے گزرے تو ان کے تجارتی مالوں سے زکوة لو۔ ہر چالیس دینار پر ایک دینار ہے۔ اس سے کم ہونے کی صورت میں اسی حساب سے کم زکوة لینا۔ یہاں تک کہ بیس دینار تک۔ اگر ثلث دینار کم ہو جائے تو اس کو چھوڑ دو اور اس مالیت سے زکوة نہ لو۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی فی المعرفة السنن والآثار (2343، 2368)، عبدالرزاق (10116، 19278)، ابن ابی شیبة (9878)۔","f":"۱۔ اموال تجارت میں فرضیت زکوة سے متعلق اختلاف ہے لیکن راجح بات یہی ہے کہ تجارتی اموال جب نصاب کو پہنچ جائیں تو ان پر سال گزرنے کے بعد زکوة فرض ہے ارشاد باری تعالیٰ ہے: ﴿يَاأَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ﴾ (البقرة: ۲۶۷) ’’اے ایمان والوں! اپنی پاکیزہ کمائی میں سے خرچ کرو۔’’امام بخاری رحمہ اللہ نے درج بالا آیت سے استدلال کرتے ہوئے‘‘بَابُ صَدَقَةِ الْكَسْبِ وَالتِّجَارَةِ’’‘‘کہ محنت اور مال تجارت سے زکوة ادا کرنے کا بیان‘‘ قائم کیا ہے۔ (صحیح بخاری، کتاب الزکوة فوق الحدیث: ۱۴۴۵)\n۲۔ موجودہ وزن کے مطابق بیس دینار ساڑھے سات تولہ سونا کے برابر ہیں، دینار میں یہی نصاب زکوة ہے جب کسی انسان کے پاس کم از کم بیس دینار ہوں تو ان پر اڑھائی فیصد یعنی چالیسواں حصہ زکوة ہے۔\n۳۔ موجودہ دور میں چونکہ درہم و دینار (سونا یا چاندی) بطور سکہ استعمال نہیں ہوتے اس لیے کاغذی کرنسی کے نصاب زکوة میں اختلاف واقع ہوا ہے۔ ہمارے استاد الشیخ حافظ عبدالمنان نور پوری رحمہ اللہ ایک سوال کے جواب میں رقم طراز ہیں ’’کاغذی کرنسی کا نصاب چاندی والا لگایا جائے گا 52½ تولہ چاندی کی مالیت کے کرنسی نوٹ ہوں تو زکوة فرض ہے۔ چالیسواں حصہ (1/40) شرح زکوة ہے۔ (احکام ومسائل: ۲/ ۴۰۶) مفتی جماعت فضیلة الشیخ حافظ عبدالستار حماد رحمہ اللہ فرماتے ہیں: ”کاغذی نوٹ سونے چاندی کے حکم میں ہیں جس شخص کے پاس سونے چاندی کے نصاب کی قیمت کے برابر یا اس سے زیادہ کرنسی نوٹ ہوں ان پر سال گزر چکا ہو اور وہ ضروریات سے فاضل ہوں تو زکوة دینا ہوگی۔‘‘ (فتاوی اصحاب الحدیث ۲/ ۲۲۱)"}],[713,"یوسف بن ماہک سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یتیم کے مال یا یتیموں کے مال کو تجارت میں لگاؤ، اسے کہیں زکوة نہ لے جائے کہ ختم کر دے۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ وابن جریج مدلس وقد عنعن: البیہقی (4/107)، المعرفة السنن والآثار لہ (2259)، عبدالرزاق (6982)۔"}],[714,"عبدالرحمن بن قاسم اپنے باپ سے روایت ہے انہوں نے کہا کہ نبی صلی اللہ علیہ وسلم کی بیوی عائشہ رضی اللہ عنہا میری اور میرے دو بھائیوں کی جو یتیم تھے پرورش فرماتی تھیں اور عائشہ رضی اللہ عنہا ہمارے مال سے زکوة دیا کرتی تھیں۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی فی المعرفة السنن والآثار (2266)، عبدالرزاق (88، 6984)۔"}],[715,"عبدالرحمن بن قاسم اپنے باپ سے روایت ہے انہوں نے کہا کہ عائشہ رضی اللہ عنہا میری اور میرے بھائی کی پرورش فرماتی تھیں اور وہ ہمارے مال سے زکوة نکالتیں۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/108)، الصغری لہ (1156)، ومالک فی المؤطا، الزکاة، باب زکوة اموال الیتمی والتجارة لہم فیہا۔"}],[716,"نافع رضی اللہ عنہ ابن عمر رضی اللہ عنہ سے روایت ہے کہ وہ یتیم کے مال سے زکوة دیتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: اخرجہ البیہقی: 4/ 108، 149۔ وعبدالرزاق (6991)۔ (6998)۔ وابن ابی شیبة (10116)۔","f":"۱۔ معلوم ہو یتیم کا مال اگر نصاب کو پہنچے تو اس میں بھی زکوة واجب ہے۔\n۲۔ یتیموں کی پرورش اور ان کے معاملات کی خبر گیری کرنا نہایت فضیلت والا عمل ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے درمیانی اور سبابہ انگلی کو ملاتے ہوئے فرمایا: «انا وكافل اليتيم في الجنة هكذا» ’’کہ میں اور یتیم کی پرورش کرنے والا جنت میں ان دو انگلیوں کی طرح اکٹھے ہوں گے۔‘‘ (صحیح بخاری، کتاب الادب، باب فضل من یعول یتیماً، رقم الحدیث: ۶۰۰۵)\n۳۔ یتیم کی پرورش کرنے والا ہی اس کے مال سے زکوة ادا کرے گا۔"}],[717,"عمرو بن دینار سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے فرمایا: یتیموں کے مال کو تجارت میں لگاؤ کہیں انہیں زکوة ختم نہ کر دے۔ (1)","",{"k":"(1) اسنادة صحیح: مالک فی المؤطا (2262)، عبدالرزاق (6990)، ابن ابی شیبة (10117)۔","f":"۱۔ یتیم کے مال میں تجارت کرنا شرعاً جائز ہے۔\n۲۔ ولی کو چاہیے کہ دیانتداری کے ساتھ یتیم کے مال سے تجارت کرے کہیں ایسا نہ ہو کہ ہر سال اس سے زکوة کی ادائیگی ہوتی رہے اور بالآخر وہ ختم ہو جائے۔\n۳۔ یتیم کا مال اگر نصاب کو پہنچے تو اس میں بھی زکوة واجب ہے۔\n۴۔ یتیم کے مال کو ناحق کھانا سنگین جرم اور کبیرہ گناہ ہے۔ ارشاد باری تعالیٰ ہے: ﴿إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا﴾ (النساء: ۱۰) ’’بے شک جو لوگ یتیموں کا مال ناحق کھاتے ہیں وہ اپنے پیٹوں میں آگ بھرتے ہیں اور عنقریب وہ دوزخ میں جائیں گے۔‘‘"}],[718,"قاسم بن محمد سے روایت ہے کہتے ہیں کہ عائشہ رضی اللہ عنہا ہمارے مال سے زکوة دیتیں اور اس سے بحرین میں تجارت ہوتی تھی۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی فی المعرفة السنن والآثار (2267)، عبدالرزاق (6983)، ابن ابی شیبة (10114، 10118)۔","f":"دیکھئے فوائد حدیث نمبر ۷۱۶، ۷۱۷۔"}],[719,"ابن عمر رضی اللہ عنہ سے مروی ہے انہوں نے فرمایا: مال میں اس وقت تک زکوة نہیں جب تک تجارت کا ارادہ نہ ہو۔ (1)","",{"k":"(1) اسنادة صحیح رواہ عدد من الثقات عن عبید اللہ بن عمر عن نافع: البیہقی (4/147)، المعرفة السنن والآثار لہ (2367)، عبدالرزاق (7103)، ابن ابی شیبة (10459)۔","f":"۱۔ معلوم ہوا عام سامان پر زکوة واجب نہیں ہے۔\n۲۔ سامانِ تجارت میں زکوة واجب ہے۔\n۳۔ مزید دیکھئے فوائد حدیث نمبر ۷۱۲۔"}],[720,"قاسم بن محمد سے روایت ہے عائشہ رضی اللہ عنہا سے کہ ان کے بھائی کی یتیم بیٹیاں ان کے ہاں زیر پرورش تھیں اور ان کے زیورات بھی تھے تو وہ ان سے زکوة نہیں نکالتی تھیں۔ (1)","",{"k":"(1) اسنادة صحیح: مالک فی الموطا (4/138)، عبدالرزاق (7052)، ابن ابی شیبة (10174)۔"}],[721,"ابن ابی ملیکہ سے روایت ہے کہ عائشہ رضی اللہ عنہا اپنے بھائی کی بیٹیوں کو سونے کے زیورات پہناتیں اور اس کی زکوة نہیں نکالتی تھیں۔ (1)","",{"k":"(1) اسنادة ضعیف من اجل ابن مؤمل: البیہقی فی المعرفة السنن والآثار (2352)۔"}],[722,"ابن عمر رضی اللہ عنہ سے روایت ہے کہ ان کی بیٹیوں اور بچیوں پر سونا (زیورات کی صورت میں) تھا اور وہ اس سے زکوة نہیں نکالتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/138)، المعرفة السنن والآثار لہ (2353)، عبدالرزاق (7047)، ابن ابی شیبة (10173)۔"}],[723,"عمرو بن دینار رضی اللہ عنہ سے روایت ہے کہتے ہیں میں نے سنا ایک آدمی جابر بن عبداللہ رضی اللہ عنہ سے پوچھ رہا تھا کیا زیورات پر زکوة ہے؟ آپ نے فرمایا: نہیں۔ اس آدمی نے کہا اگر (زیورات) ایک ہزار دینار تک پہنچ جائیں تو؟ جابر رضی اللہ عنہ نے فرمایا: اس سے بھی زیادہ ہوں (تو بھی نہیں)۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/138)، المعرفة السنن والآثار لہ (2354)، عبدالرزاق (7046)، ابن ابی شیبة (10177)، الدارقطنی (2/107)۔","f":"۱۔ سونے اور چاندی کے زیورات کی زکوة کے فرض ہونے میں اختلاف ہے البتہ راجح بات یہی ہے کہ اگر زیورات حد نصاب (7½ تولہ سونا یا 52½ تولہ چاندی) کو پہنچ جائیں تو ان پر زکوة فرض ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا عمومی فرمان ہے: ’’ما من صاحب ذھب ولا فضة لا یؤدی زکاة’’،‘‘کہ جو بھی سونے اور چاندی کا مالک زکوة ادا نہیں کرتا...’’(مسلم، رقم: ۹۷۸) اس عموم میں سونے اور چاندی کے زیورات بھی داخل ہیں۔ اسی طرح رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک عورت آئی اور اس کی بیٹی کے ہاتھ میں سونے کے دو کنگن تھے آپ علیہ السلام نے اس سے دریافت کیا:‘‘أتؤدین زکوة ھذا؟’’‘‘کیا تو اس کی زکوة دیتی ہے؟’’اس عورت نے نفی میں جواب دیا تو آپ علیہ السلام نے فرمایا:‘‘أیسرک ان یسورک اللہ بھما یوم القیامة سوارین من نار’’‘‘کیا تمہیں یہ بات پسند ہے کہ ان کے بدلے قیامت کے دن تجھے آگ کے دو کنگن پہنائے جائیں۔’’یہ بات سن کر اس عورت نے دونوں کنگن اتار دیے اور نبی علیہ السلام کے سامنے ڈال کر کہنے لگی:‘‘ھما للہ ولرسولہ’’‘‘یہ اللہ اور اس کے رسول کے لیے ہیں۔‘‘ (سنن ابی داؤد، کتاب الزکاة، باب الکنز ما ھو؟ وزکاة الحلی، رقم: ۱۵۶۳ - سنن نسائی، رقم: ۲۴۸۱)\n۲۔ ایک حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے سیدہ عائشہ رضی اللہ عنہا کو چاندی کی انگوٹھیاں پہنے دیکھا تو فرمایا: ’’تؤدین زکاتھن’’‘‘کیا تم ان کی زکوة دیتی ہو؟’’انہوں نے نفی میں جواب دیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘ھو حسبک من النار’’‘‘تمہیں جہنم میں لے جانے کے لیے یہی کافی ہیں۔‘‘ (سنن ابی داؤد، کتاب الزکاة، باب الکنز ما ھو؟ وزکاة الحلی، رقم: ۱۵۶۵ - سنن دارقطنی، رقم: ۱۹۳۴) درج بالا احادیث اسی بات کی متقاضی ہیں کہ زیورات میں بھی زکوة ہے بشرطیکہ وہ حد نصاب کو پہنچ جائیں۔"}],[724,"ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اوقیہ سے کم چاندی پر زکوة واجب نہیں ہے۔‘‘ (1)","",{"k":"(1) البخاری (1459)، مسلم (979)۔"}],[725,"ابوسعید خدری رضی اللہ عنہ بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اوقیہ سے کم میں زکوة نہیں ہے۔‘‘ (1)","",{"k":"(1) البخاری (1447)۔"}],[726,"ایک دوسری سند سے بھی یہ حدیث اسی طرح مروی ہے۔ (1)","",{"k":"(1) مسلم (979)۔","f":"۱۔ چاندی کا نصاب پانچ اوقیہ ہے۔ ایک اوقیہ چالیس درہم کا ہوتا ہے۔ (دیکھئے: سنن ترمذی، رقم: ۶۲۷)\n۲۔ چاندی میں زکوة کی مقدار چالیسواں حصہ ہے جیسا کہ سیدنا علی رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اذا کانت لک مائتا درھم وحال علیھا الحول ففیھا خمسة دراھم» ’’جب تیرے پاس دو سو درہم ہوں اور ان پر ایک سال پورا بیت جائے تو ان میں پانچ درہم زکوة ہے۔‘‘ (سنن ابی داؤد، کتاب الزکاة، باب زکاة السائمة، رقم: ۱۵۷۳)"}],[727,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اور دفن شدہ خزانے میں پانچواں حصہ ہے۔‘‘ (1)","",{"k":"(1) البخاری (6912)، مسلم (1710)۔"}],[728,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’دفینہ میں پانچواں حصہ ہے۔‘‘ (1)","",{"k":"(1) صحیح: النسائی (2497)، احمد (2/382)، ابویعلی (6308)، الدارمی (2384)، الحمیدی (1080)، البیہقی فی المعرفة السنن والآثار (2386)۔"}],[729,"ابن مسیب اور ابو سلمہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: دفینہ (مدفون خزانہ) میں پانچواں حصہ ہے۔“ (1)","",{"k":"(1) صحیح سبق موصولاً انظر الحدیث الذی السابق برقم (728)۔","f":"۱۔ ’’رکاز‘‘ سے مراد کسی اجاڑ بے آباد زمین میں مدفون خزانہ ہے جس کا مالک معلوم نہ ہو۔ اس میں سے پانچواں حصہ بیت المال کا ہے۔ جب کہ باقی مال اس شخص کی ملکیت ہوگا جسے خزانہ ملا۔ آج کل ایسے اموال کو حکومتوں کا مکمل قبضہ میں لے لینا غیر شرعی ہے۔"}],[730,"عمرو بن شعیب اپنے باپ سے وہ اپنے دادا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اس خزانہ کے متعلق فرمایا جس کو ایک آدمی نے جاہلیت کی ویران زمین سے پایا۔ ’’اور اگر تو نے اس کو آبادی والی بستی سے پایا ہے یا شارع عام سے تو اس کا اعلان کر، اور اگر تو نے اسے جاہلیت کی ویران جگہ یا غیر آباد بستی سے پایا ہے تو اس میں اور دفینہ میں پانچواں حصہ ہے۔‘‘ (1)","",{"k":"(1) صحیح من غیر ھذا الطریق: ابوداود (1710)، احمد (2/180، 186، 203، 208)، وصححہ ابن خزیمة (2327، 2328)، ابن الجارود (670)، الحاکم (2/65)۔","f":"۱۔ معلوم ہوا اگر آباد راستوں اور رہائشی بستیوں میں کسی آدمی کو خزانہ ملے تو یہ رکاز نہیں بلکہ اس کا ایک سال تک اعلان کیا جائے گا۔ اور اگر اجاڑ، ویران اور غیر آباد بستیوں میں سے خزانہ حاصل ہوتو اس میں اور رکاز میں خمس کی ادائیگی کرنا ہوگی۔\n۲۔ رکاز کے مال میں زکوة نہیں بلکہ خمس ہے اور اس کا مصرف اللہ کے فرمان: ﴿وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ﴾ (الانفال: ۴۱) ’’اور جان لو کہ تم جس قسم کی غنیمت حاصل کرو اس میں سے پانچواں حصہ اللہ اس کے رسول، قرابت داروں، یتیموں، مساکین اور مسافروں کا ہے۔‘‘ (الدرر البہیة، کتاب الخمس)"}],[731,"شعبی رحمہ اللہ روایت بیان کرتے ہیں کہ ایک آدمی علی رضی اللہ عنہ کے پاس اور اس نے کہا مجھے سواد مقام پر غیر آباد جگہ سے پندرہ سو درہم ملے ہیں۔ علی رضی اللہ عنہ نے فرمایا: میں اس میں بڑا واضح فیصلہ کروں گا۔ اگر تو نے ایک ایسی غیر آباد جگہ سے یہ درہم پائے ہیں جو دوسری بستی سے ملی ہوئی ہے تو یہ پیسے ان بستی والوں کے ہیں اور اگر تو نے ایک ایسی بستی سے پائے کہ جس کی غیر آباد جگہ دوسری سے نہیں ملی ہوئی تو تیرے لیے چار خمس اور ایک خمس ہمارے لیے ہے پھر ایک اور خمس تیرے لیے ہے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/156)، المعرفة السنن والآثار لہ (2391)، ابن ابی شیبة (10772)۔","f":"۱۔ اگر کسی آدمی کو خزانہ وغیرہ ملے تو وہ اسے حاکم وقاضی کے سامنے پیش کرے اور پھر اس کے فیصلے کے مطابق اس میں تصرف کرے۔\n۲۔ خمس بیت المال میں جمع کرانے کے بعد باقی مال کا وہ شخص مالک ہے جسے مال ملا ہو۔"}],[732,"ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اور دفینہ میں پانچواں حصہ (زکوة) ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (727)۔","f":"دیکھئے فوائد حدیث نمبر ۷۲۲، ۷۳۰۔"}],[733,"ابن عباس رضی اللہ عنہ سے روایت ہے ان سے عنبر کے متعلق پوچھا گیا تو آپ نے فرمایا: اگر اس میں کچھ ہے تو وہ پانچواں حصہ ہے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/146)، المعرفة السنن والآثار لہ (2364)، عبدالرزاق (6976)، ابن ابی شیبة (10065)۔"}],[734,"طاوؤس رحمہ اللہ سے روایت ہے کہ ابن عباس رضی اللہ عنہ سے عنبر کے متعلق پوچھا گیا تو آپ نے فرمایا: اگر اس میں کچھ ہے تو وہ پانچواں حصہ ہے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (733)","f":"۱۔ ’’عنبر‘‘ مچھلی کی ایک قسم ہے۔\n۲۔ امام بخاری رحمہ اللہ فرماتے ہیں: ’’قال الحسن فى العنبر واللؤلؤ الخمس فانما جعل النبى صلى الله عليه وسلم فى الركاز الخمس، ليس فى الذى يصاب فى الماء’’‘‘حسن بصری رحمہ اللہ نے کہا، کہ عنبر اور موتیوں میں پانچواں حصہ (خمس) لازم ہے حالانکہ نبی اکرم صلی اللہ علیہ وسلم نے رکاز میں پانچواں حصہ مقرر فرمایا ہے اور رکاز اس کو نہیں کہتے جو پانی میں ملے۔’’(یعنی اس میں خمس وغیرہ نہیں ہے۔) (بخاری، کتاب الزکاة، باب ما یستخرج من البحر، قبل الحدیث: ۱۴۹۸) حافظ ابن حجر رحمہ اللہ اسی باب کے تحت فتح الباری میں فرماتے ہیں:‘‘وذھب الجمہور الی انہ لا یجب فیہ شیء’’‘‘جمہور کے نزدیک دریا سے نکالی گئی اشیاء پر کچھ بھی لازم نہیں ہے۔‘‘ (فتح الباری: ۳/ ۴۶۳)\n۳۔ امام شوکانی رحمہ اللہ فرماتے ہیں: ’’ویجب فیما یغنم فی القتال وفی الرکاز ولا یجب فیما عدا ذلک’’‘‘کہ مال غنیمت اور رکاز میں پانچواں حصہ (خمس) دینا ضروری ہے اور ان کے علاوہ کسی اور چیز میں خمس واجب نہیں ہے۔‘‘ (الدرر البہیة، کتاب الخمس)"}],[735,"ابن عباس رضی اللہ عنہ نے فرمایا: عنبر میں زکوة نہیں ہے، یہ تو ایک ایسی چیز ہے جس کو دریا کنارے پر پھینک دیتا ہے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/146)، المعرفة السنن والآثار لہ (2363)، ابن ابی شیبة (10058)۔"}],[736,"ابن عباس رضی اللہ عنہ سے مروی ہے انہوں نے کہا: عنبر میں کچھ بھی نہیں، یہ تو ایک ایسی چیز ہے جس کو دریا کنارے پر پھینک دیتا ہے۔ (1)","",{"k":"(1) اسنادة صحیح: اخرجہ البیہقی: 4/ 146۔ وابن ابی شیبة، رقم: 10059۔ والبخاری تعلیقاً قبل الحدیث (1498)۔","f":"۱۔ ابن عباس رضی اللہ عنہ کا یہ فرمان بھی اس بات کی تائید کرتا ہے کہ عنبر وغیرہ میں خمس یا زکوة نہیں ہے۔ مزید دیکھئے فوائد حدیث نمبر ۷۳۳، ۷۳۴۔"}],[737,"عتاب بن اسید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انگور کی زکوة کے متعلق فرمایا: ’’اس کا اندازہ لگایا جائے گا جس طرح کہ کھجور کے درختوں کا لگایا جاتا ہے۔ پھر اس کی زکوة کشمش میں دی جائے گی جس طرح کہ کھجور کے درختوں کی زکوة کھجوروں سے دی جاتی ہے۔‘‘ (1)","",{"k":"(1) اسنادة ضعیف لانقطاعہ: ابوداود (1603، 1604)، وقال وسعید لم یسمع من عتاب شیئاً، ابن ماجہ (1819)، الترمذی (644)۔"}],[738,"اسی سابقہ سند سے ہے کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے پاس (ان لوگوں کو) بھیجتے جو ان کے انگوروں اور پھلوں کا اندازہ لگاتے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (737)","f":"۱۔ مذکورہ روایات اگر چہ انقطاع کی وجہ سے ضعیف ہیں تاہم مسئلہ اسی طرح ہی ہے کہ جو زرعی اجناس خشک کر کے ذخیرہ کی جاتی ہیں ان میں زکوة ہے۔\n۲۔ جو پھل خشک ہونے سے قبل تازہ استعمال ہو اس سے متعلق مقدار کا تعین اندازے سے کیا جائے گا تا کہ خشک ہونے پر طے شدہ مقدار بطور زکوة ادا کی جا سکے۔\n۳۔ نبی صلی اللہ علیہ وسلم اہل خیبر کی کھجوروں کا تخمینہ لگانے کے لیے سیدنا عبداللہ بن رواحہ رضی اللہ عنہ کو بھیجا کرتے تھے۔ (دیکھئے: سنن ابن ماجہ، رقم: ۱۸۲۰)"}],[739,"نافع رحمہ اللہ سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہ فرماتے تھے: پھلوں اور کھیتیوں کا صدقہ (زکوة) جو کھجوروں یا انگوروں یا کھیتیوں یا جو یا سلت (حجاز میں پیدا ہونے والا جو جو گیہوں کے مشابہ ہوتا ہے) جو زمین سے تری حاصل کرنے والا ہو، یا نہر سے سیراب کیا گیا ہو، یا چشمہ سے پانی پلایا گیا ہو یا بارش سے سیراب ہوا ہو۔ اس میں دسواں حصہ ہے۔ ہر دس سے ایک حصہ ہوگا، اور جس کو پانی کھینچ کر ڈولوں یا جانوروں سے لا کر سیراب کیا گیا اس میں نصف العشر (بیسواں حصہ) ہے ہر بیسویں میں سے ایک حصہ ہوگا، جو کھیت ڈولوں سے پانی نکال کر سینچا جائے یا جانور پر پانی لا کر اس میں سے بیسواں حصہ (پیداوار کا) لیا جائے گا۔ (1)","",{"k":"(1) البخاری (1483)۔","f":"۱۔ بارانی زمین کی زرعی پیداوار میں سے عشر (دسواں حصہ) جبکہ کنویں، ٹیوب ویل وغیرہ سے سیراب ہونے والی فصل میں سے نصف العشر (بیسواں حصہ) بطور زکوة ادا کرنا ضروری ہے۔\n۲۔ زرعی پیداوار کی زکوة کی ادائیگی کٹائی کے موقع پر ہوگی اگر زمین سال میں دو یا تین فصلیں دیتی ہے تو ہر فصل کی کٹائی پر عشر یا نصف العشر کی ادائیگی ہوگی، کیونکہ اس میں سال گزرنے کی شرط نہیں بلکہ فصل کا ہونا شرط ہے۔ ارشاد باری تعالیٰ ہے: ﴿وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾ ’’اور اس کی کٹائی کے دن اس کا حق ادا کرو‘‘ (الانعام: ۱۴۱)\n۳۔ زرعی پیداوار کا نصاب پانچ وسق ہے مزید دیکھئے۔ فوائد حدیث نمبر ۷۴۵۔"}],[740,"سعد بن ابی ذباب بیان فرماتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اسلام لایا، پھر میں نے کہا، میری قوم کے مسلمان لانے کی وجہ سے ان کے مالوں سے کسی کو زکوة لینے کے لیے مقرر فرمائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح کیا اور مجھے ان پر عامل مقرر فرما دیا۔ پھر ابو بکر رضی اللہ عنہ نے پھر عمر رضی اللہ عنہ نے بھی مجھے عامل بنایا۔ راوی کہتے ہیں کہ سعد معززین میں سے تھے۔ سعد کہتے ہیں میں نے اپنی قوم سے شہد کے متعلق بات کی اور ان سے کہا اس میں زکوة ہے کیونکہ وہ مال جس سے زکوة نہ دی جائے اس میں بہتری نہیں ہے۔ انہوں نے کہا: کتنی ہے؟ سعد کہتے ہیں میں نے کہا، دسواں حصہ ہے۔ سعد کہتے ہیں میں ان سے دسواں حصہ لے کر عمر رضی اللہ عنہ کے پاس آیا اور انہیں آگاہ کیا تو عمر رضی اللہ عنہ نے اسے بیچ کر اس کی قیمت کو مسلمانوں کے صدقات میں جمع کر دیا۔ (1)","",{"k":"(1) ضعیفٌ: البیہقی (4/127)، احمد (4/79)، ابن ابی شیبة (10053)، الطبرانی فی الکبیر (6/43، 5458)۔","f":"مذکورہ روایت ضعیف ہے تاہم شہد کی زکوة سے متعلق مروی ہے۔ عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے شہد سے دسواں حصہ وصول فرمایا۔ (سنن ابن ماجہ، رقم: ۱۸۲۴، سنن ابی داؤد، رقم: ۱۶۰۲)\nشہد چونکہ مال اور زمینی پیداوار سے حاصل ہونے والی چیز ہے لہذا اس سے زکوة ادا کی جائے۔ امام شوکانی رحمہ اللہ فرماتے ہیں ’’ویجب فی العسل العُشْر’’‘‘شہد میں دسواں حصہ زکوة، واجب ہے۔‘‘ (الدرر البہیة، کتاب الزکاة، باب زکاة النباتات)"}],[741,"عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ گندم اور تیل جس کو پانی نکال کر سیراب کیا جاتا اس سے بیسواں حصہ لیتے تھے۔ وہ اس سے یہ چاہتے تھے کہ کثرت سے اشیاء مدینہ تک پہنچائی جائیں۔ اور دالوں میں سے دسواں حصہ زکوة کا لیا کرتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (9/210)، المعرفة السنن والآثار لہ (5542)، عبدالرزاق (10126، 10127، 19282)، ابن ابی شیبة (10584)۔"}],[742,"سائب بن یزید کہتے ہیں میں عمر بن خطاب رضی اللہ عنہ کے زمانہ میں، مدینہ کے بازار میں عبداللہ بن عتبہ کے ساتھ عامل تھا، عبداللہ بن عتبہ نبطیوں سے عشر لیتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (9/210)، المعرفة السنن والآثار لہ (5543)، عبدالرزاق (10117، 19279)۔","f":"۱۔ نبط: عجم کی ایک قوم کا نام ہے جو عراق عجم اور عراق عرب کے درمیان رہتی ہے۔ ان کو نبطی اس لیے کہتے ہیں کہ وہ پانی نکالنے میں بڑے ماہر تھے کیونکہ یہ لوگ زراعت پیشہ تھے اور مزارعین کو پانی نکالنے، کنویں کھودنے کی ہمیشہ ضرورت رہتی ہے۔ (لغات الحدیث: ۴/ ۲۹۲، ۲۹۳)۔\n۲۔ معلوم ہوا سیدنا عمر بن خطاب رضی اللہ عنہ نبط کے کافروں سے گیہوں اور تیل کا بیسواں جبکہ دالوں وغیرہ سے دسواں حصہ وصول کرتے تھے۔\n۳۔ معلوم ہوا تیل اور گیہوں سے نصف العشر اس لیے لیتے تاکہ یہ اشیاء زیادہ سے زیادہ مدینہ میں آئیں اور مدینہ والوں کو اس سے فائدہ پہنچے۔\n۴۔ اہل کتاب یا کفار سے تو صرف جزیہ وصول کیا جاتا ہے جبکہ سیدنا عمر نبطیوں سے عشر یا نصف العشر بھی وصول کرتے تھے اس مسئلہ کی وضاحت کرتے ہوئے امام مالک رحمہ اللہ فرماتے ہیں: ’’ووضعت الجزیة علی اھل الکتاب صغاراً لھم فھم ما کانوا ببلدھم الذین صالحوا علیہ لیس علیھم شیء سوی الجزیة فی شیء من اموالھم الا ان یتجروا فی بلاد المسلمین ویختلفوا فیھا فیؤخذ منھم العشر فیما یریدون من التجارات وذلک انما وضعت علیھم الجزیة وصالحوا علیھا علی ان یقروا ببلادھم ویقاتل عنھم عدوھم فمن خرج منھم من بلادہ الی غیرھا یتجر الیھا فعلیہ العشر......’’‘‘اہل کتاب پر جزیہ ان کی ذلت کے لیے مقرر کیا گیا ہے جب تک وہ اپنے ان علاقوں میں رہیں جہاں انہوں نے (مسلمانوں سے) صلح کی تو ان سے جزیہ کے علاوہ کچھ نہیں لیا جائے گا۔ لیکن اگر وہ مسلمانوں کے دیگر شہروں میں بغرض تجارت آئیں جائیں تو ان کے مالِ تجارت سے دسواں حصہ لیا جائے گا۔ کیونکہ ان پر جزیہ کا تقرر اور ان سے صلح اس شرط پر ہوئی تھی کہ وہ اپنے شہروں میں رہیں گے اور مسلمان ان کی حفاظت کریں گے تو جو شخص ان میں سے اپنے شہر سے تجارت کے لیے کسی اور شہر جائے گا تو اس کے مالِ تجارت سے عشر (دسواں حصہ) لیا جائے گا۔‘‘ (مؤطا امام مالک: کتاب الزکاة، باب جزیة اھل الکتاب والمجوس: ۱/ ۲۷۹)"}],[743,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم کھجوروں میں زکوة نہیں ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (724)"}],[744,"ابو سعید خدری رضی اللہ عنہ بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم (غلہ) میں زکوة نہیں ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (725)"}],[745,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم (غلہ) میں زکوة نہیں ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (726)","f":"۱۔ زرعی پیداوار سے متعلقہ جو مسائل سابقہ احادیث میں بیان ہوئے ہیں ان احادیث میں ان کے نصاب کا ذکر کیا گیا ہے۔ گویا اناج اور غلے کا نصاب پانچ وسق ہے اس سے کم پیداوار پر زکوة نہیں ہے۔\n۲۔ ایک وسق ساٹھ صاع کا ہوتا ہے اور ایک صاع ۲۱۰۰ گرام کا لہذا پانچ وسق ۶۳۰ کلو یعنی ۱۵ من ۳۰ کلو کے ہوئے۔ (فتاوی اصحاب الحدیث از شیخ الحدیث عبدالستار حماد: ۱/ ۱۸۲، احکام و مسائل از حافظ عبدالمنان نور پوری رحمہ اللہ: ۱/ ۲۶۹) عشر یا نصف العشر جمیع پیداوار سے ادا کیا جائے گا اس سے اخراجات منہا نہیں ہوں گے کیونکہ شریعت نے صرف پانی کے خرچے کا اعتبار کیا ہے۔ اس کے علاوہ کسی خرچہ کا کوئی اعتبار نہیں۔\n۳۔ بعض اہل علم کے نزدیک ایک صاع اڑھائی کلو کے مساوی ہے لہذا ان کے ہاں نصاب ۷۵۰ کلو گرام بنتا ہے۔\n۴۔ مزید دیکھئے فوائد حدیث نمبر ۷۳۹۔"}],[746,"ابوحمید ساعدی رضی اللہ عنہ سے روایت ہے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ اسد کے ایک آدمی کو جس کا نام ابن لتبیہ تھا، صدقہ وصول کرنے کے لیے عامل بنایا۔ جب وہ واپس آئے تو اس نے کہا یہ آپ کا مال ہے اور یہ مجھے ہدیہ (تحفہ) میں ملا ہے۔ نبی صلی اللہ علیہ وسلم منبر پر کھڑے ہو گئے اور آپ نے فرمایا: ’’کیا ہوا عامل کو کہ ہم اسے اپنے بعض مال لانے کے لیے بھیجتے ہیں، اور وہ آ کر کہتا ہے، یہ تمہارا (بیت المال) مال ہے اور یہ مجھے تحفہ دیا گیا ہے۔ وہ اپنے والد یا والدہ کے گھر کیوں نہ بیٹھا رہا، دیکھتا وہاں بھی اسے ہدیہ ملتا ہے یا نہیں۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے۔ اس (مال زکوة) میں سے اگر کوئی شخص کچھ بھی (ناجائز) لے گا تو وہ اسے قیامت کے دن اپنی گردن پر اٹھائے حاضر ہوگا۔ اگر اونٹ ہے تو بلبلاتا آئے گا، اگر گائے ہے تو ڈکارتی ہوئی آئے گی اور اگر بکری ہے تو ممیاتی ہوئی آئے گی۔’’پھر آپ نے اپنے ہاتھ مبارک اٹھائے حتی کہ ہم نے آپ کی بغل مبارک کی سفیدی بھی دیکھ لی اور فرمایا:‘‘اے اللہ! میں نے تیرا حکم پہنچا دیا، اے اللہ! میں نے تیرا حکم پہنچا دیا۔‘‘ (1)","",{"k":"(1) البخاری (2597)، مسلم (1832)۔"}],[747,"ابوحمید ساعدی رضی اللہ عنہ سے روایت ہے کہ میری آنکھوں نے دیکھا اور میرے کانوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا اور تم زید بن ثابت رضی اللہ عنہ سے دریافت کرلو، یعنی اسی طرح سابقہ حدیث کی مثل۔ (1)","",{"k":"(1) البخاری (925، 6636، 6979)، مسلم (1832)۔","f":"۱۔ صدقہ و زکوة کی وصولی کے لیے عاملین کا تقرر درست ہے۔\n۲۔ حاکم وقت کی ذمہ داری ہے کہ عاملین سے حساب و کتاب لے تاکہ معاملات صاف وشفاف رہیں۔\n۳۔ سرکاری ملازمین کو دوران ڈیوٹی تحفے تحائف لینے کا کوئی حق نہیں ہے۔\n۴۔ قومی امانتوں کو ذاتی تصرفات میں لانا نا جائز ہے۔\n۵۔ موجودہ دور میں تخفے بطور رشوت دیے جاتے ہیں جو کسی صورت بھی درست نہیں۔\n۶۔ دنیا کی خیانتیں روز قیامت بہت بوجھل ثابت ہوں گی۔\n۷۔ عام حالات میں تحائف کا تبادلہ درست ہے۔"}],[748,"طاؤوس رضی اللہ عنہ سے روایت ہے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبادہ بن صامت رضی اللہ عنہ کو صدقہ وصول کرنے کے لیے عامل بنایا، اور فرمایا: ’’اے ابوالولید! اللہ سے ڈرو! کہیں ایسا نہ ہو کہ تو قیامت کے دن اپنی گردن پر اونٹ لائے اور وہ بلبلا رہا ہو یا گائے لائے جو ڈکار رہی ہو یا بکری جو ممیا رہی ہو۔’’عبادہ بن صامت رضی اللہ عنہ نے کہا اے اللہ کے رسول! کیا یہ (واقعتاً) ایسے ہی ہے؟ آپ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘ہاں، مجھے اس ذات کی قسم جس کے ہاتھ میں میری جان ہے مگر جس پر اللہ نے رحم کیا۔‘‘ عبادہ رضی اللہ عنہ نے کہا: مجھے اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث کیا میں دو چیزوں پر بھی آئندہ عامل نہیں بنوں گا۔ (1)","",{"k":"(1) اسنادة ضعیف لارسالہ: البیہقی (4/158)، المعرفة السنن والآثار لہ (2396)، عبدالرزاق (6949، 6953)، الحمیدی (895)۔"}],[749,"عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صدقہ جس مال میں ملتا ہے اس کو تباہ کر دیتا ہے۔‘‘ (1)","",{"k":"(1) اسنادة ضعیف لضعف محمد بن عثمان بن صفوان: البیہقی (4/159)، المعرفة السنن والآثار لہ (2400)، الحمیدی (237)، البغوی (1563)۔"}],[750,"اسلم رضی اللہ عنہ سے روایت ہے وہ بیان کرتے ہیں اس نے عمر بن خطاب رضی اللہ عنہ سے کہا: ان اونٹوں میں ایک اندھی اونٹنی ہے۔ عمر رضی اللہ عنہ نے فرمایا: کیا جزیہ (ٹیکس) کے جانوروں میں سے ہے یا صدقہ (زکوة) کے جانوروں میں سے ہے؟ اسلم نے کہا جزیہ (ٹیکس) کے جانوروں میں سے ہے۔ فرمایا: اس پر جزیہ کی نشانی موجود ہے۔“ (1)","",{"k":"(1) صحیح: البیہقی (7/25)، المعرفة السنن والآثار لہ (4043)، ومالک فی الموطأ، الزکاة، باب جزیة اھل الکتاب والمجوس۔","f":"۱۔ معلوم ہوا ریاست کے حکمران ریاست کے وسائل کے محافظ ونگہبان ہوتے ہیں۔\n۲۔ سیدنا عمر رضی اللہ عنہ بیت المال پر کڑی نگاہ رکھتے تھے۔\n۳۔ عہد فاروق میں صدقہ اور جزیہ کے اموال پر علیحدہ علیحدہ نشانات لگائے جاتے تھے۔\n۴۔ ریاستی وسائل کو شیر مادر سمجھ کر بے دریغ استعمال کرنے والوں اور رعایا کے حقوق سے بے خبر مسلم حکمرانوں کو سیدنا عمر رضی اللہ عنہ کا طرز حکومت اپنانا چاہیے۔"}],[751,"عثمان بن عفان رضی اللہ عنہ کے آزاد کردہ غلام بیان کرتے ہیں کہ میں عثمان رضی اللہ عنہ کے ساتھ، گرمیوں کے دنوں میں ان کے مال کے ساتھ مدینہ کے قریبی آبادیوں میں تھا، جب انہوں نے دیکھا کہ ایک آدمی، اونٹ کے دو بچوں کو ہانک رہا ہے اور زمین پر پروانوں کی طرح گرمی کی شدت کی وجہ سے جا رہا ہے۔ عثمان رضی اللہ عنہ نے کہا اس آدمی کو کیا ہے، کیوں نہ یہ مدینہ میں رہا حتی کہ ٹھنڈک ہو جاتی، پھر چلتا پھر وہ آدمی قریب ہوا تو فرمایا: دیکھو یہ کون ہے؟ میں نے کہا، ایک آدمی چادر سے اپنے آپ کو ڈھانپے اونٹ کے بچوں کو ہانک رہا ہے۔ پھر وہ آدمی اور قریب ہوا تو انہوں نے پھر کہا: دیکھو! میں نے دیکھا تو وہ عمر بن خطاب رضی اللہ عنہ تھے۔ میں نے کہا یہ تو امیر المومنین ہیں۔ عثمان رضی اللہ عنہ کھڑے ہوئے اور اپنا سر دروازے سے باہر نکالا تو انہیں گرمی کی لو سے تکلیف پہنچی اپنا سر واپس داخل کر لیا حتی کہ جب وہ قریب آگئے تو پوچھا، آپ کس لیے اس وقت نکلے؟ تو عمر رضی اللہ عنہ نے فرمایا: صدقہ کے اونٹوں کے دو بچے پیچھے رہ گئے جبکہ صدقہ کے اونٹ چلے جا چکے ہیں، میں نے چاہا کہ ان کو بھی چراگاہ میں ان سے ملا دوں، میں ڈرا کہیں یہ ضائع نہ ہو جائیں کہ پھر اللہ مجھ سے ان کے متعلق دریافت کریں۔ عثمان رضی اللہ عنہ نے فرمایا: اے امیر المومنین! آؤ ہمارے پانی اور سایہ کی طرف، (یعنی پانی پی لو اور سایہ میں آرام کر لو) عمر رضی اللہ عنہ نے فرمایا: تم اپنے سایہ میں ٹھہرے رہو۔ عثمان رضی اللہ عنہ نے فرمایا: ہمارے پاس آپ کی ضرورت کی چیزیں ہیں، عمر رضی اللہ عنہ نے فرمایا: تم اپنے سایہ میں ٹھہرے رہو پھر وہ چلے گئے۔ عثمان رضی اللہ عنہ نے فرمایا: جو آدمی چاہتا ہے کہ وہ کسی امانت دار، مضبوط آدمی کو دیکھے وہ ان کی طرف دیکھ لے۔ پھر عثمان رضی اللہ عنہ واپس ہماری طرف (سایہ میں) آئے اور سوچ وبچار میں مشغول ہو گئے۔ (1)","",{"k":"(1) اسنادة ضعیف لتردد الثقة ولجھالة مولی عثمان (3743)۔"}],[752,"محمد بن کعب القرظی سے روایت بیان کرتے ہیں کہ آدم علیہ السلام نے حج کیا تو ان سے فرشتے ملے اور انہوں نے کہا اے آدم علیہ السلام آپ کا حج قبول ہو گیا۔ ہم نے آپ سے دو ہزار سال پہلے حج کیا تھا۔ (1)","",{"k":"(1) اسنادة صحیح (5/177)، المعرفة السنن والآثار لہ (3126)۔","f":"۱۔ حج کے لغوی معنی قصد اور ارادہ کے ہیں یہ اسلام کے پانچ بنیادی ارکان میں سے ایک ہے۔ اس کی ادائیگی ہر صاحب استطاعت مسلمان پر زندگی میں ایک دفعہ فرض ہے۔\n۲۔ مذکورہ حدیث سے معلوم ہوا حج ایک قدیم عبادت ہے انسان ازل سے ہی اس کی ادائیگی کرتے آ رہے ہیں۔"}],[753,"ابو صالح الحنفی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’حج، جہاد اور عمرہ نفلی عبادت ہے۔‘‘ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (4/348)، المعرفة السنن والآثار لہ (2703)، ابن ابی شیبة (13647)۔","f":"۱۔ مذکورہ روایت اگرچہ مرسل ہونے کی وجہ سے سنداً ضعیف ہے تاہم حج وعمرہ کی فضیلت صحیح احادیث سے ثابت ہے۔\n۲۔ حج کی فضیلت کی بابت نبی علیہ السلام نے فرمایا: «والحج المبرور ليس له جزاء الا الجنة» کہ حج مبرور کا بدلہ صرف جنت ہے۔ (صحیح بخاری، ابواب العمرة، باب وجوب العمرة وفضلها، رقم: ۱۷۷۳)\n۳۔ میں عمرہ کی بھی بڑی اہمیت وفضیلت ہے ارشاد باری تعالیٰ ہے: ﴿واتموا الحج والعمرة لله﴾ (البقرة: ۱۹۶) ’’اور اللہ کے لیے حج وعمرہ کو پورا کرو۔‘‘ عام دنوں کی نسبت رمضان المبارک کے مقدس مہینہ میں عمرہ کرنے کا اجر وثواب بہت زیادہ ہے۔ نبی علیہ السلام نے فرمایا: «فانّ عمرة فى رمضان تقضى حجة معى» کہ رمضان میں عمرہ کرنا میرے ساتھ حج کرنے کے مترادف ہے۔“ (صحیح بخاری، کتاب جزاء الصيد باب حج النساء، رقم: ۱۸۶۳)"}],[754,"محمد بن عباد بن جعفر بیان کرتے ہیں کہ ہم عبداللہ بن عمر رضی اللہ عنہما کے ہاں بیٹھے تھے کہ میں نے ان کو فرماتے سنا ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا اور کہا: حج (کے ارکان ادا کرنے والا کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پراگندہ بالوں اور خوشبو سے دور رہنے والا۔’’دوسرا آدمی کھڑا ہوا اور اس نے پوچھا سبیل کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘زادِ راہ اور سواری۔‘‘ (1)","",{"k":"(1) اسنادة ضعیف جداً، فان ابراھیم بن یزید الخوزی متروک الحدیث ولہ طرق اخری وکلھا ضعیفة: الترمذی (813)، ابن ماجہ (2896)۔","f":"۱۔ شریعت نے سفر حج میں زادِ راہ لے کر جانے کی بہت زیادہ تاکید فرمائی ہے۔ ارشادِ باری تعالیٰ ہے: ﴿وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴾ (البقرة: ۱۹۷) ’’اور سفری اخراجات لے کر چلو بے شک بہترین توشہ تقویٰ (سوال سے اجتناب) ہے۔’’اس آیت کے شان نزول سے متعلق سیدنا ابن عباس رضی اللہ عنہما سے مروی ہے۔ وہ فرماتے ہیں: «كان اهل اليمن يحجون ولا يتزودون ويقولون نحن المتوكلون، فاذا قدموا المدينة سألوا الناس فانزل الله تعالى ﴿وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴾»‘‘جب اہل یمن حج کے لیے نکلتے تو ساتھ زادِ راہ نہ لاتے اور کہتے ہم اللہ پر توکل کرنے والے ہیں۔ پھر جب مدینہ آتے تو لوگوں سے سوال کرنے لگتے تو اللہ تعالیٰ نے یہ آیت نازل فرمائی۔‘‘ (صحیح بخاری، کتاب الحج، باب قول الله تعالى وتزوّدوا.... الخ، رقم: ۱۵۳۳) معلوم ہوا مشروع اسباب اختیار کیے بغیر اللہ پر توکل درست نہیں لہذا حج وعمرہ کے سفر کے لیے انسان کو رہن سہن، کھانے پینے اور دیگر تمام لوازمات کا بندوبست کرنے کے بعد گھر سے روانہ ہونا چاہیے۔"}],[755,"نبی صلی اللہ علیہ وسلم کے صحابی عبداللہ بن ابی اوفی رضی اللہ عنہ سے روایت ہے وہ بیان کرتے ہیں کہ میں نے آپ صلی اللہ علیہ وسلم سے ایک ایسے آدمی کے متعلق پوچھا جس نے حج نہیں کیا تو کیا وہ حج کی ادائیگی کے لیے قرض مانگ لے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’نہیں۔‘‘ (1)","",{"k":"(1) اسنادة حسن: البیہقی (4/333)، المعرفة السنن والآثار لہ (2664)، ابن ابی شیبة (15865)۔","f":"۱۔ حج وعمرہ کی فرضیت کے لیے طاقت و قدرت اور استطاعت کا ہونا شرط ہے ارشادِ باری تعالیٰ ہے: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا﴾ (آل عمران: ۹۷) ’’اور لوگوں پر اللہ کا یہ حق ہے کہ جو اس کے گھر پہنچنے کی استطاعت رکھتے ہوں وہ اس کا حج کریں۔‘‘\n۲۔ مذکورہ حدیث سے معلوم ہوا قرض لے کر حج کرنا درست نہیں کیونکہ اللہ رب العزت نے انسانوں کو کسی ایسی چیز کا مکلف نہیں بنایا جو ان کی طاقت میں نہ ہو ارشادِ باری تعالیٰ ہے: ﴿لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا﴾ ’’اللہ کسی نفس کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے۔‘‘ (البقرة: ۲۸۶)۔ مزید دیکھیے فوائد حدیث نمبر: ۷۵۴۔"}],[756,"ابن جریج کہتے ہیں میں نے نافع رضی اللہ عنہ سے کہا کیا آپ نے عبداللہ بن عمر رضی اللہ عنہما کو حج کے مہینوں کے نام بیان کرتے سنا؟ نافع رضی اللہ عنہ نے کہا: ہاں وہ شوال، ذیقعدہ اور ذوالحجہ کا نام لیتے تھے۔ ابن جریج کہتے ہیں میں نے نافع رضی اللہ عنہ سے کہا اگر کوئی آدمی ان سے پہلے حج کے لیے تلبیہ کہے، احرام باندھے تو؟ نافع رضی اللہ عنہ نے فرمایا: میں نے اس کے متعلق ان سے کچھ نہیں سنا۔ (1)","",{"k":"(1) صحیح: البیہقی (4/342)، المعرفة السنن والآثار لہ (2687)، ابن ابی شیبة (13629)، الدارقطنی (2/226)، وصححہ الحاکم (2/272)۔","f":"۱۔ ارشادِ باری تعالیٰ ہے: ﴿الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ﴾ ’’کہ حج کے مہینے معلوم ہیں۔‘‘ (البقرة: ۱۹۷) لہذا سنت یہی ہے کہ حج کا احرام حج کے مہینوں ہی میں باندھا جائے، دوسرے مہینوں میں حج کا احرام باندھنا درست نہیں کیونکہ حج کا وقت معلوم مہینے ہیں جس طرح وقت سے قبل نماز درست نہیں اسی طرح وقت سے قبل حج کے لیے احرام باندھنا بھی درست نہیں۔\n۲۔ معلوم ہوا شوال، ذوالقعدہ اور ذوالحجہ کے پہلے دس دن ’’اشہر الحج‘‘ ہیں۔"}],[757,"ابوزبیر سے روایت ہے کہ انہوں نے جابر بن عبداللہ رضی اللہ عنہما سے سنا ان سے ایک آدمی کے متعلق پوچھا گیا کہ کیا وہ حج کے لیے احرام حج کے مہینوں سے پہلے باندھ لے؟ تو آپ نے فرمایا: نہیں۔ (1)","",{"k":"(1) اسنادة ضعیف لعنعة ابن جریج: البیہقی (4/343)، المعرفة السنن والآثار لہ (2690)، الدارقطنی (2/234)، ابن ابی شیبة (14618)۔"}],[758,"عطاء رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے احرام باندھنے کے لیے جگہیں مقرر کیں، اس وقت فرمایا: ’’آدمی اپنے گھر والوں (بیوی)، اور اپنے کپڑوں سے فائدہ اٹھائے یہاں تک کہ اس، اس جگہ پر آجائے جو احرام باندھنے کے لیے ہے۔‘‘ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (5/30)، المعرفة السنن والآثار لہ (2768)۔","f":"مذکورہ روایت اگرچہ مرسل ہونے کی وجہ سے سنداً ضعیف ہے تاہم یہ بات درست ہے کہ میقات سے احرام باندھ کر جب تلبیہ شروع کر دیا جائے تو احرام کھولنے تک اس کے آداب اور شرعی پابندیوں کا لحاظ رکھنا ضروری ہے۔ احرام باندھنے سے پہلے اور احرام کو کھولنے کے بعد آدمی معمول کے تمام شرعی طور پر جائز کام کر سکتا ہے۔"}],[759,"ابن عمر رضی اللہ عنہما سے روایت ہے بیان فرماتے ہیں کہ مدینہ میں مدینہ والوں میں سے ایک آدمی مسجد میں کھڑا ہوا اور اس نے کہا، اے اللہ کے رسول (صلی اللہ علیہ وسلم)! آپ ہمیں کہاں سے احرام باندھنے کا حکم دیتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’مدینہ کے لوگ ذوالحلیفہ سے احرام باندھیں، شام کے لوگ جحفہ سے اور نجد کے لوگ قرن (منازل) سے احرام باندھیں۔’’ابن جریج رضی اللہ عنہ کہتے ہیں مجھ سے نافع رضی اللہ عنہ نے کہا، وہ یہ بھی سمجھتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:‘‘یمن والے یلملم سے احرام باندھیں۔‘‘ (1)","",{"k":"(1) اخرجہ البخاری (133)، (1525) ومسلم (1182)۔"}],[760,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مدینہ کے لوگ ذوالحلیفہ سے احرام باندھیں، شام کے لوگ جحفہ سے اور نجد کے لوگ قرن (منازل) سے احرام باندھیں۔’’عبداللہ بن عمر رضی اللہ عنہما نے فرمایا۔ وہ (صحابہ رضی اللہ عنہم) یہ سمجھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘اور یمن والے یلملم سے احرام باندھیں۔‘‘ (1)","",{"k":"(1) اخرجہ البخاری (1527)، (1528) ومسلم (1182)۔"}],[761,"عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے انہوں نے فرمایا مدینہ والوں کو حکم دیا گیا کہ وہ ذوالحلیفہ سے احرام باندھیں، اور شام والے جحفہ سے اور نجد والے قرن (منازل) سے احرام باندھیں۔ ابن عمر رضی اللہ عنہما نے فرمایا: یہ تین وہ بھی مقامات ہیں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے خود سنے اور مجھے بتایا گیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اور یمن والے یلملم سے احرام باندھیں۔‘‘ (1)","",{"k":"(1) البخاری (7344)، مسلم (1182)۔","f":"۱۔ میقات سے مراد وہ مقام ہے جہاں سے حج وعمرہ کے لیے مکہ جانے والوں کے لیے احرام باندھنا ضروری ہے۔\n۲۔ مذکورہ احادیث سے معلوم ہوا نبی علیہ السلام نے مختلف علاقے کے لوگوں کے لیے مختلف میقات کا تقرر کیا ہے۔ (i) ذوالحلیفہ: اہل مدینہ اور ان کے راستے سے آنے والوں کے لیے ذوالحلیفہ احرام باندھنے کی جگہ ہے اسے آج کل ’’آبار علی’’، کہتے ہیں۔ یہ مکہ مکرمہ سے تقریباً ۴۵۰ کلومیٹر کے فاصلے پر ہے۔ (ii) جحفة: شام، مصر، ترکی، روم، لیبیا، یورپ امریکہ وغیرہ سے آنے والوں کے لیے احرام باندھنے کی جگہ جحفہ ہے۔ یہ مکہ مکرمہ سے تقریباً ۱۸۷ کلومیٹر کے فاصلے پر شمال مغرب میں واقع ہے۔ (iii) قرن المنازل: یہ اہل نجد، حجاز وغیرہ کی طرف سے آنے والوں کے لیے احرام باندھنے کی جگہ ہے۔ یہ مکہ مکرمہ سے تقریباً ۹۴ کلومیٹر کی دوری پر واقع ہے۔ (iv) یلملم: یمن، چین، انڈونیشیا، ہندوستان، جاوہ، افغانستان، پاکستان اور بنگلہ دیش وغیرہ کے ممالک سے حج وعمرہ کے لیے مکہ مکرمہ جانے والوں کے لیے یلملم احرام باندھنے کی جگہ ہے یہ مکہ مکرمہ سے تقریباً ۹۲ کلومیٹر کے فاصلہ پر واقع ہے اسے آج کل‘‘السعدیہ‘‘ کہتے ہیں۔ (v) ذَاتُ العرق: اہل عراق ایران اور مکہ کی شمال مشرقی جانب سے آنے والوں کا میقات، ذات العرق ہے۔ یہ مکہ سے تقریباً ۹۴ کلومیٹر کے فاصلہ پر واقع ہے۔"}],[762,"طاؤوس بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ، شام والوں کے لیے جحفہ، نجد والوں کے لیے قرن منازل، اور یمن والوں کے لیے یلملم میقات مقرر کیے، پھر فرمایا: ’’یہ وہاں کے رہنے والوں، اس جگہ پر آنے والوں جو وہاں کے رہائشی نہیں اور حج یا عمرہ کا ارادہ لے کر آئے ہیں ان کے لیے احرام باندھنے کی جگہ ہے۔ لیکن جن کا قیام میقات اور مکہ کے درمیان ہے تو وہ احرام اسی جگہ سے باندھیں جہاں سے انہوں نے سفر شروع کرنا ہے یہاں تک کہ مکہ والے مکہ سے ہی احرام باندھ لیں۔‘‘ (1)","",{"k":"(1) صحیح موصولاً: اخرجہ البخاری (1524)، (1530) ومسلم (1181)۔"}],[763,"ابن عباس رضی اللہ عنہ کے واسطہ سے نبی صلی اللہ علیہ وسلم سے احرام باندھنے کی جگہوں کے بارے میں اسی طرح مروی ہے جس طرح سفیان رحمہ اللہ کی حدیث میقاتوں کے متعلق ہے۔ (1)","",{"k":"(1) صحیح موصولاً: البخاری (1524، 1530)، مسلم (1181)۔"}],[764,"ابن عباس رضی اللہ عنہ سے روایت ہے بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ، شام والوں کے لیے جحفہ، یمن والوں کے لیے یلملم اور نجد والوں کے لیے قرن (منازل) کو میقات مقرر کیا، اور جن کا قیام میقات اور مکہ کے درمیان ہے تو وہ احرام وہیں سے باندھیں جہاں سے وہ سفر شروع کریں۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (762) اسنادة ضعیف لضعف لیث بن ابی سلیم، الا ان المتن صحیح کما سبق برقم (762، 763)","f":"معلوم ہوا جو لوگ میقات کی حدود سے باہر ہیں وہ میقات پر پہنچ کر احرام باندھیں گے لیکن جو لوگ مقرر کردہ میقات کی حدود سے اندر ہیں وہ اپنے اپنے گھروں سے احرام باندھ کر روانہ ہوں گے۔"}],[765,"ابو زبیر سے روایت ہے کہ انہوں نے جابر بن عبد اللہ رضی اللہ عنہ سے سنا جب ان سے احرام باندھنے کی جگہ کے متعلق پوچھا گیا تو انہوں نے فرمایا: ’’میں نے اس کو سنا، پھر خاموش ہو گئے میرے خیال سے وہ نبی صلی اللہ علیہ وسلم کے متعلق فرما رہے تھے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مدینہ والے ذوالحلیفہ سے احرام باندھیں گے اور دوسرے راستہ سے آنے والے جحفہ سے، اور احرام باندھیں گے عراق والے ذات عرق سے، اور نجد والے قرن منازل سے اور یمن والے یلملم سے احرام باندھیں گے۔‘‘ (1)","",{"k":"(1) مسلم (1183)۔"}],[766,"عطاء رحمہ اللہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ میقات مقرر کیا، مغرب والوں کے لیے جحفہ، مشرق والوں کے لیے ذات عرق، نجد والوں کے لیے قرن، اور جس نے یمن والوں میں سے یا ان کے علاوہ دوسروں نے نجد کا راستہ اختیار کیا ان کے لیے قرن ذوالمعادن اور یمن والوں کے لیے یلملم۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ وقد صحیح موصولاً کما سبق برقم (765) اخرجہ البیہقی: 5/ 27۔ وفی المعرفة السنن والآثار لہ (2750)۔"}],[767,"ابن جریج رحمہ اللہ کہتے ہیں میں نے عطاء رحمہ اللہ سے مراجعت کی اور میں نے کہا لوگ سمجھتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ذات عرق کو میقات مقرر نہیں کیا اور نہ ہی اس وقت مشرق والے تھے۔ عطاء نے کہا اس وقت عراق نہیں تھا مشرق والے تھے۔ عطاء نے کہا ہم نے اسی طرح سنا ہے کہ آپ نے ذات عرق یا عقیق کو مشرق والوں کے لیے احرام باندھنے کی جگہ مقرر کیا۔ اور فرمایا: اس وقت عراق نہیں تھا اور لیکن مشرق والے تھے۔ انہوں نے اس بات کی نسبت نبی صلی اللہ علیہ وسلم کے علاوہ صحابہ رضی اللہ عنہم میں سے کسی سے نہیں کی، لیکن وہ اس بات کا انکار کرتے ہیں (کہ نبی صلی اللہ علیہ وسلم نے میقات مقرر نہیں کیا) مگر یہ (کہتے ہیں) کہ اس کو نبی صلی اللہ علیہ وسلم نے میقات مقرر کیا۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (5/28)، المعرفة السنن والآثار لہ (2751)۔"}],[768,"طاوس رحمہ اللہ سے روایت ہے وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ذات عرق کو میقات مقرر نہیں کیا اور نہ ہی اس وقت مشرق والے تھے۔ بلکہ یہ لوگوں نے ذات عرق میقات مقرر کیا ہے۔ امام شافعی رحمہ اللہ نے فرمایا: میرے خیال میں بھی بات اسی طرح ہے جس طرح طاوس رحمہ اللہ نے کہی اور بہتر علم اللہ کے پاس ہے۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی فی المعرفة السنن والآثار (2752)۔","f":"۱۔ امام شافعی رحمہ اللہ کا طاوس رحمہ اللہ سے موافقت اختیار کرنا ان دونوں بزرگوں کا اجتہاد ہے کیونکہ صحیح احادیث سے یہ بات ثابت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اہل عراق کے لیے ذات عرق کو میقات مقرر فرمایا ہے جیسا کہ پیچھے گزر چکا ہے دیکھئے حدیث نمبر: ۷۶۵۔\n۲۔ اہل عراق اس وقت مسلمان نہیں تھے لیکن ان کے لیے میقات مقرر کر دیا گیا کیونکہ جہاں نبی صلی اللہ علیہ وسلم نے اس علاقے کے فتنوں سے متنبہ فرمایا وہیں آپ نے ان لوگوں کے اسلام کے لیے دعا بھی فرمائی۔ نبی صلی اللہ علیہ وسلم نے فرمایا: «اللهم اقبل بقلوبهم» اے اللہ ان کے دلوں کو (اسلام کی طرف) متوجہ فرما دے۔ (سنن ابن ماجہ، رقم: ۲۹۱۵)\n۳۔ نبی صلی اللہ علیہ وسلم کا اہل عراق کے غیر مسلم ہونے کے باوجود ان کے لیے میقات مقرر کرنا اس بات کی طرف اشارہ تھا کہ عنقریب یہ لوگ مسلمان ہو جائیں گے۔\n۴۔ اہل عراق کے لیے نبی صلی اللہ علیہ وسلم کا میقات مقرر کرنا آپ صلی اللہ علیہ وسلم کے معجزات اور دلائل نبوت سے ہے۔"}],[769,"ابو الشعثاء کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے مشرق والوں کے لیے کوئی بھی میقات مقرر نہیں کیا یہ تو لوگوں نے قرن کے حساب سے ذات عرق مقرر کر دیا۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ، وابن جریج مدلس وقد عنعن: البیہقی فی المعرفة السنن والآثار (2753)۔"}],[770,"جابر بن عبد اللہ رضی اللہ عنہ سے روایت ہے اور انہوں نے نبی صلی اللہ علیہ وسلم کے حج کا ذکر کیا اور انہیں وہیں سے تلبیہ کہنے کا حکم دیا اور آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم چلتے ہوئے منی کی طرف جاؤ تو تلبیہ کہو۔‘‘ (1)","",{"k":"(1) صحیح من غیر ھذا الطریق: مسلم (1214)۔","f":"۱۔ حجتہ الوداع کے موقع پر نبی صلی اللہ علیہ وسلم نے یہ حکم ان صحابہ کرام رضی اللہ عنہم کو دیا تھا جن کے پاس قربانی کے جانور نہیں تھے آپ نے انہیں حکم فرمایا کہ وہ عمرہ کر کے احرام کھول دیں اور قران کی نیت فسخ کر کے حج تمتع کریں۔\n۲۔ حج تمتع کرنے والا میقات سے صرف عمرہ کی نیت سے احرام باندھتا ہے اور پھر عمرہ کر کے احرام کھول کر احرام کی پابندیوں سے آزاد ہو جاتا ہے۔ پھر آٹھ ذوالحجہ کو حج کا احرام باندھ کر مناسک حج ادا کرتا ہے۔ حج تمتع کرنے والا چونکہ وہیں سے احرام باندھ کر تلبیہ شروع کر دیتا ہے اس لیے مذکورہ بالا حدیث سے یہ استدلال کیا گیا ہے کہ مکہ سے احرام باندھنے والا اپنی قیام گاہ سے تلبیہ شروع کر دے گا۔\n۳۔ معلوم ہوا حج تمتع کرنے والا اپنی قیام گاہ سے یوم الترویہ (۸ ذوالحجہ) کو تلبیہ حج کہتے ہوئے منی کی طرف روانہ ہوگا۔"}],[771,"ابو الشعثاء رحمہ اللہ سے روایت ہے کہ اس نے ابن عباس رضی اللہ عنہ کو دیکھا جو شخص بغیر احرام کے میقات سے گزر جاتا اسے واپس لوٹاتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/29، 30)، المعرفة السنن والآثار لہ (2764)۔","f":"۱۔ مذکورہ مسئلہ میں اختلاف ہے۔ امام نووی رحمہ اللہ فرماتے ہیں کہ امام مالک، ابوحنیفہ، شافعی، احمد اور جمہور علماء رحمہم اللہ کا موقف یہ ہے کہ اگر کوئی (حج کرنے والا) شخص میقات سے احرام باندھے بغیر گزر گیا تو وہ گناہ گار ہے اور اسے بطور فدیہ ایک بکرا ذبح کرنے پڑے گا البتہ اس کا حج صحیح ہوگا۔ (شرح النووی علی مسلم، کتاب الحج، باب مواقیت الحج والعمرة)\n۲۔ اگر میقات سے گزر جانے والا دوبارہ واپس میقات پر آ کر احرام باندھے اور پھر مناسک حج ادا کرے تو اس پر فدیہ نہیں ہے۔\n۳۔ اگر کوئی شخص ذاتی غرض سے، حج و عمرہ کے ارادہ کے بغیر مکہ مکرمہ جا رہا ہو تو اس کے لیے مواقیت سے احرام باندھنا ضروری نہیں ہے۔ کیونکہ نبی صلی اللہ علیہ وسلم نے مواقیت کے سلسلہ میں ’’ممن اراد الحج أو العمرة‘‘ فرمایا ہے۔ دیکھئے گزشتہ حدیث نمبر: ۷۶۲۔"}],[772,"محرش الکعبی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو جعرانہ سے نکلے اور (مکہ میں داخل ہو کر) عمرہ کیا اور صبح جعرانہ میں تھے گویا کہ آپ نے رات وہیں گزاری۔ (1)","",{"k":"(1) اخرجہ الترمذی (935)۔ وقال ’’حسن غریب‘‘ وابوداود (1996)۔ والنسائی (2866)","f":"۱۔ میقات مکانی: اس سے مراد وہ جگہیں ہیں جہاں سے حج و عمرہ کے لیے مکہ جانے والے احرام باندھتے ہیں ان جگہوں سے بغیر احرام باندھے گزرنا جائز نہیں۔ یہ پانچ جگہیں ہیں دیکھئے تفصیل کے لیے فوائد حدیث نمبر ۷۵۹۔\n۲۔ میقات زمانی: اس سے مراد وہ ایام اور اوقات ہیں جن میں احرام باندھ کر حج و عمرہ کیا جاتا ہے۔ عمرہ کرنے کے لیے سال کے کسی بھی مہینے اور کسی بھی وقت احرام باندھا جا سکتا ہے لیکن حج کے مہینے مقرر ہیں اس لیے حج کے لیے صرف انہیں مقرر کردہ مہینوں میں ہی احرام باندھا جائے گا۔ تفصیل کے لیے دیکھئے فوائد حدیث نمبر ۷۵۶۔\n۳۔ عمرہ دن اور رات کے اوقات میں کسی بھی وقت کیا جا سکتا ہے۔\n۴۔ نبی صلی اللہ علیہ وسلم نے جعرانہ سے احرام باندھا عمرہ کیا اور پھر رات کو ہی جعرانہ روانہ ہو گئے۔ گویا آپ نے رات جعرانہ میں گزاری۔\n۵۔ جعرانہ: مکہ مکرمہ سے قریب حدود حرم سے باہر ایک جگہ کا نام ہے۔\n۶۔ بعض علماء کے نزدیک مکہ میں مقیم لوگوں کے لیے حدود حرم سے باہر تنعیم یا جعرانہ مقام سے عمرہ کے لیے احرام باندھ کر آنا ضروری ہے جبکہ حج میں ایسا نہیں ہے جبکہ بعض علماء کے نزدیک ہر دو صورت میں اپنی رہائش گاہ سے احرام باندھ لینا جائز ہے۔ جیسا کہ پیچھے گزر چکا ہے۔ دیکھئے فوائد حدیث نمبر ۷۷۰، ۷۶۲۔"}],[773,"ابن جریج سے ایک دوسری سند سے یہ حدیث اسی طرح مروی ہے۔ ابن جریج کہتے ہیں کہ وہ (محرش نہیں) مخرش ہے۔ امام شافعی رحمہ اللہ فرماتے ہیں ابن جریج نے درست کہا کیونکہ ان کا بیٹا مخرش ہمارے پاس ہے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (772)"}],[774,"عبد الرحمن بن ابی بکر بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے اسے حکم دیا کہ وہ عائشہ رضی اللہ عنہا کو اپنے پیچھے بٹھا کر لے جائے اور انہیں تنعیم سے عمرہ کرائے۔ (1)","",{"k":"(1) البخاری (1784)، مسلم (1212)۔","f":"۱۔ سیدہ عائشہ رضی اللہ عنہا نے حج الوداع کے موقع پر عمرہ کا احرام باندھا تھا لیکن حیض کی وجہ سے عمرہ کیے بغیر انہیں حج کا احرام باندھنا پڑ گیا۔\n۲۔ سیدہ عائشہ رضی اللہ عنہا کی خواہش تھی کہ وہ عمرہ بھی ادا کریں چنانچہ نبی صلی اللہ علیہ وسلم نے ان کے بھائی عبد الرحمن بن ابی بکر رضی اللہ عنہ کو انہیں عمرہ کروانے کا کہا۔\n۳۔ تنعیم کو آج کل مسجد عائشہ کہا جاتا ہے یہ عمرہ کے لیے میقات نہیں ہے لہذا عمرہ کے لیے جانے والے حضرات کا بار بار مسجد عائشہ جا کر عمرہ کے لیے احرام باندھنا اور آ کر مناسک عمرہ ادا کرنا درست نہیں ہے۔\n۴۔ مکہ میں مقیم انسان کا اپنی اقامت گاہ سے احرام باندھ کر عمرہ کرنا درست ہے۔\n۵۔ یہ عمرہ سیدہ عائشہ رضی اللہ عنہا نے کیا تھا۔ عبدالرحمن رضی اللہ عنہ نے ان کے ساتھ نہیں کیا تھا۔\n۶۔ حج تمتع میں حج سے پہلے عمرہ کیا جاتا ہے حج کے بعد عمرہ کرنے سے حج تمتع نہیں بنتا۔"}],[775,"ابن مسیب رحمہ اللہ سے روایت ہے کہ عائشہ رضی اللہ عنہا نے سال میں دو دفعہ عمرہ کیا ایک دفعہ ذوالحلیفہ سے اور ایک دفعہ جحفہ سے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/344)، المعرفة السنن والآثار لہ (2700)۔","f":"معلوم ہوا سال میں ایک، دو بلکہ کئی عمرے بھی کیے جا سکتے ہیں۔"}],[776,"قاسم بن محمد رحمہ اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کی بیوی عائشہ رضی اللہ عنہا نے سال میں دو مرتبہ عمرہ کیا۔ صدقہ بن یسار کہتے ہیں میں نے کہا، کیا اس پر کسی نے اعتراض نہیں کیا؟ تو قاسم رحمہ اللہ نے (بطور تعجب) سبحان اللہ کہا کہ ام المومنین پر (اعتراض)! صدقہ کہتے ہیں میں نے یہ بات کہنے کی وجہ سے شرم محسوس کی۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی فی المعرفة السنن والآثار (2699)۔"}],[777,"نافع رحمہ اللہ سے روایت ہے بیان کرتے ہیں کہ عبداللہ بن عمر رضی اللہ عنہما نے عبداللہ بن زبیر رضی اللہ عنہ کے عہد میں ہر سال دو عمرے کیے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/344)، المعرفة السنن والآثار لہ (2701)۔"}],[778,"انس بن مالک رضی اللہ عنہ کے بچوں میں سے ایک بیٹا کہتا ہے کہ ہم مکہ میں انس بن مالک رضی اللہ عنہ کے ساتھ تھے۔ جب ان کے سر کے بال نکل آتے تو وہ پھر عمرہ کرنے کے لیے نکل جاتے۔ (1)","",{"k":"(1) اسنادة ضعیف لإبھام بعض ولد انس: البیہقی (4/344)، المعرفة السنن والآثار لہ (2698)۔"}],[779,"مجاہد رحمہ اللہ سے روایت ہے کہ علی بن ابی طالب رضی اللہ عنہ نے فرمایا کہ ہر مہینہ میں عمرہ ہے۔ (1)","",{"k":"(1) اسنادة ضعیف، لإنقطاعہ، فان مجاھداً لم یسمع من علی بن ابی طالب: البیہقی (4/344)، المعرفة السنن والآثار لہ (2697)، ابن ابی شیبة (12723)۔"}],[780,"مجاہد رحمہ اللہ سے مروی ہے کہ علی رضی اللہ عنہ نے فرمایا: ہر مہینے میں عمرہ ہے۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (779)"}],[781,"قاسم بن محمد سے روایت ہے کہ عائشہ رضی اللہ عنہا نے ایک سال میں دو دفعہ یا کئی دفعہ عمرہ کیا۔ صدقہ کہتے ہیں کہ میں نے کہا: کیا کسی نے ان پر اعتراض نہیں کیا؟ صدقہ کہتے ہیں قاسم نے کہا ام المومنین پر (اعتراض) صدقہ کہتے ہیں مجھے شرم آئی۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (776)"}],[782,"نافع رحمہ اللہ سے روایت ہے کہ ابن عمر رضی اللہ عنہما نے ایک سال میں دو دفعہ یا فرمایا کئی دفعہ عمرہ کیا۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/344)، المعرفة السنن والآثار لہ (2701)۔"}],[783,"نافع رحمہ اللہ سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہ نے بیت المقدس سے احرام باندھا۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/30)، المعرفة السنن والآثار لہ (2769)، ابن ابی شیبة (12674)۔"}],[784,"عبدالرحمن بن ابی بکر بیان کرتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ میں عائشہ رضی اللہ عنہا کو عمرہ کرواؤں تو میں نے انہیں تنعیم سے عمرہ کروایا۔ انہوں نے ہی یا ان کے علاوہ کسی اور نے حدیث میں کہا: محصب کی رات۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (774)","f":"۱۔ محصب: اس مقام کو کہتے ہیں جہاں پر منی میں کنکریاں مارتے ہیں۔\n۲۔ معلوم ہوا محصب کی رات بھی عمرہ کرنا جائز ہے۔ مزید دیکھئے فوائد حدیث نمبر ۷۷۴۔"}],[785,"جعفر بن محمد اپنے باپ سے بیان کرتے ہیں کہ علی رضی اللہ عنہ دو عیدوں کے دن، جمعہ کے دن، عرفہ کے دن اور جب احرام باندھنے کا ارادہ کرتے تو غسل فرماتے تھے۔ (1)","",{"k":"(1) اسنادة ضعیف جداً، لضعف شیخ الشافعی ولإنقطاعہ، بین محمد بن علی بن الحسین وعلی بن ابی طالب: البیہقی فی المعرفة السنن والآثار (1864)، عبدالرزاق (5751)۔"}],[786,"عائشہ رضی اللہ عنہا سے روایت ہے بیان فرماتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم احرام باندھتے تو میں آپ کے احرام کے لیے احرام باندھنے سے پہلے اور اسی طرح بیت اللہ کے طواف زیارت سے پہلے حلال ہونے کے لیے خوشبو لگایا کرتی تھی۔ (1)","",{"k":"(1) البخاری (1539)، مسلم (1189)۔"}],[787,"عبدالرحمن بن قاسم اپنے باپ سے روایت ہے انہوں نے عائشہ رضی اللہ عنہا سے کہ انہوں نے اپنے دونوں ہاتھ پھیلائے اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو احرام کے لیے جب آپ نے احرام باندھا اور اسی طرح بیت اللہ کے طواف زیارت سے پہلے حلال ہونے کے لیے اپنے ان دونوں ہاتھوں سے خوشبو لگائی۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم: (786)"}],[788,"عائشہ رضی اللہ عنہا سے روایت ہے بیان فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو احرام کے لیے جب آپ نے احرام باندھا اور اسی طرح بیت اللہ کے طواف زیارت سے پہلے حلال ہونے کے لیے اپنے ان دونوں ہاتھوں سے خوشبو لگائی۔ (1)","",{"k":"(1) البخاری (5928)، مسلم (1189)۔"}],[789,"عروہ بیان کرتے ہیں کہ میں عائشہ رضی اللہ عنہا سے سنا آپ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو احرام باندھنے کے لیے اور حلال ہونے کے لیے خوشبو لگائی۔ عروہ کہتے ہیں میں نے عائشہ رضی اللہ عنہا سے کہا کون سی خوشبو؟ تو انہوں نے فرمایا: سب سے اچھی خوشبو۔ عثمان کہتے ہیں: ہشام نے یہ حدیث میرے علاوہ کسی سے روایت نہیں کی۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (788)","f":"۱۔ احرام باندھنے سے پہلے جسم کی ضروری صفائی کے ساتھ ساتھ احرام کے لیے غسل کرنا مسنون ہے۔ نبی صلی اللہ علیہ وسلم نے احرام باندھنے کے لیے خود بھی غسل فرمایا اور حیض و نفاس والی عورتوں کو بھی غسل کا حکم دیا۔\n۲۔ غسل سے فارغ ہو کر مردوں کے لیے عمدہ سے عمدہ خوشبو کا استعمال بھی جائز ہے چاہے اس کا اثر بعد میں ہی باقی کیوں نہ رہے۔\n۳۔ محرم آدمی کے لیے خوشبو کا استعمال درست نہیں۔ نبی صلی اللہ علیہ وسلم نے حالت احرام میں وفات پانے والے صحابی سے متعلق حکم فرمایا: «ولا تمسوه طيبا» ’’اسے خوشبو نہ لگاؤ۔‘‘ (بخاری، رقم: ۱۲۶۷۔ مسلم، رقم: ۱۲۰۶)\n۴۔ معلوم ہوا طواف افاضہ سے پہلے خوشبو کا استعمال بھی مسنون ہے۔"}],[790,"عائشہ رضی اللہ عنہا سے روایت ہے بیان فرماتی ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں خوشبو کی چمک (احرام کے) تین دن بعد دیکھی۔ (1)","",{"k":"(1) البخاری (271)، مسلم (1190)۔","f":"۱۔ احرام سے قبل خوشبو کا استعمال درست ہے چاہے اس خوشبو کا اثر احرام باندھنے کے بعد بھی باقی رہے۔\n۲۔ مانگ نکالنا مسنون ہے۔"}],[791,"حسن بن زید اپنے باپ سے روایت ہے انہوں نے کہا میں نے ابن عباس رضی اللہ عنہ کو حالت احرام میں دیکھا، اور ان کے سر پر خوشبو شیرے کی طرح تھی۔ (1)","",{"k":"(1) فی اسنادہ ضعف لأجل الحسن بن زید: البیہقی (5/35)، المعرفة السنن والآثار لہ (2786)۔"}],[792,"عائشہ بنت سعید کہتی ہیں میں نے اپنے باپ کو احرام کے وقت مشک اور ذریرہ (خوشبو کی اقسام) سے خوشبو لگائی۔ (1)","",{"k":"(1) حسن: البیہقی (5/35)، المعرفة السنن والآثار لہ (2785)، ابن ابی شیبة رقم (1348)۔"}],[793,"عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کیا۔ (1)","",{"k":"(1) مسلم (1211)۔","f":"۱۔ حج افراد: حج کی تین مشروع اقسام میں سے ایک حج مفرد ہے۔ جس میں حاجی صرف حج کی نیت کر کے احرام باندھتا اور تلبیہ کہتا ہے پھر اعمال حج مکمل ہونے تک احرام ہی میں رہتا ہے۔\n۲۔ مذکورہ حدیث سے واضح ہوتا ہے کہ نبی صلی اللہ علیہ وسلم نے حج افراد کیا تھا۔ جبکہ اس سے آئندہ حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کی لبیک کہی تھی۔ صحیح بخاری و مسلم میں سیدنا انس بن مالک رضی اللہ عنہ سے مروی ایک حدیث میں ہے نبی اکرم صلی اللہ علیہ وسلم نے حج و عمرہ کی لبیک کہی تھی۔ (بخاری، رقم: ۴۳۵۳، ۴۳۵۴۔ مسلم، رقم: ۱۲۳۲)\n۳۔ اس طرح کی مروی روایات میں مختلف علماء نے مختلف انداز میں تطبیق دی ہے:\n(i) رسول اللہ صلی اللہ علیہ وسلم نے پہلے حج مفرد کے ارادہ سے لبیک کہی اور بعد میں حج قران کی لبیک پکاری لہذا ہر صحابی نے اپنے اپنے علم کے مطابق جو سنا بیان کر دیا۔ (شرح الزرقانی علی موطا امام مالک)\n(ii) رسول اللہ صلی اللہ علیہ وسلم شروع ہی سے حج قران کے ارادہ سے نکلے تھے۔ اور حج قران کرنے والے کو اجازت ہے کہ وہ کسی وقت ’’لبیک بحجة’’کسی وقت‘‘لبیک بعمرة’’اور کسی وقت‘‘لبیک بحجة و عمرة‘‘ کہہ لے اس لیے صحابہ کرام رضی اللہ عنہم نے نبی صلی اللہ علیہ وسلم کی زبان اقدس سے جو سنا سو بیان فرما دیا۔ (مرعاة المفاتیح، شرح حدیث نمبر ۲۵۶۹)\n(iii) امام نووی رحمہ اللہ فرماتے ہیں آپ صلی اللہ علیہ وسلم نے آغاز میں حج مفرد کا احرام باندھا بعد میں عمرہ کو بھی ساتھ ملا لیا اور آپ قارن ہو گئے۔ اور یہی مذہب صحیح و مختار ہے۔ (شرح النووی علی مسلم، کتاب الحج، باب فی الافراد والقران)\n(iv) رسول اللہ صلی اللہ علیہ وسلم نے حج قران کیا تھا اور حج تمتع کی تمنا فرمائی تھی تفصیل آگے آئے گی۔"}],[794,"عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صرف حج کا احرام باندھا تھا۔ (1)","",{"k":"(1) البخاری (1562)، مسلم (1211)۔"}],[795,"عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کیا۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (794)"}],[796,"اسود عبداللہ (بن مسعود) رضی اللہ عنہ سے بیان کرتے ہیں کہ انہوں نے حج افراد کا حکم دیا۔ انہوں نے کہا کہ میں نے کہا: انہوں نے اس بات کو پسند کیا ہے کہ ان دونوں میں سے ہر ایک کے لیے پراگندہ حالت اور سفر ہو اور ان کا یہ خیال ہے کہ حج قران افضل ہے، جب ان سے کوئی فتویٰ مانگے تو وہ اسی کا فتویٰ دیتے ہیں، جبکہ عبداللہ رضی اللہ عنہ خود حج قران کو ناپسند کرتے تھے۔ (1)","",{"k":"(1) اسنادة ضعیف، لضعف ابی حمزة میمون: البیہقی (5/5)، المعرفة السنن والآثار لہ (2730)۔"}],[797,"عائشہ رضی اللہ عنہا سے روایت ہے انہوں نے فرمایا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کے ارادہ کے لیے نکلے، یہاں تک کہ جب ہم مقام سرف یا اس کے قریب پہنچے تو میں حیضہ ہو گئی۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور میں رو رہی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہیں کیا ہو گیا، کیا حیضہ ہو گئی؟’’میں نے کہا، ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘یہ ایک ایسی چیز ہے جس کو اللہ تعالیٰ نے آدم کی بیٹیوں کے لیے لکھ دیا ہے اس لیے تم بیت اللہ کے طواف کے علاوہ حج کے افعال پورے کر لو۔‘‘ عائشہ رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کی طرف سے گائے کی قربانی کی۔ (1)","",{"k":"(1) البخاری (294)، مسلم (1211)۔","f":"۱۔ معلوم ہوا حائضہ عورت بیت اللہ کے طواف کے سوا دیگر حجاج کی طرح تمام اعمال حج ادا کرے گی۔\n۲۔ اسلام ایک مکمل ضابطہ حیات ہے جس میں تمام انسانی کمزوریوں کا پورا پورا خیال رکھا گیا ہے۔\n۳۔ معلوم ہوا نبی صلی اللہ علیہ وسلم نے حج کے موقع پر ازواج مطہرات رضی اللہ عنہن کی طرف سے ایک گائے ذبح کی تھی۔"}],[798,"جابر بن عبداللہ رضی اللہ عنہ فرماتے ہیں کہ علی رضی اللہ عنہ صدقات کی وصولی کے عمل سے فارغ ہو کر (مکہ) تشریف لائے تو نبی صلی اللہ علیہ وسلم نے ان سے پوچھا: ’’اے علی! تم نے کس چیز کا احرام باندھا ہے؟’’انہوں نے عرض کی جس کا نبی صلی اللہ علیہ وسلم نے احرام باندھا ہے (میں نے بھی اس کا باندھا ہے) تو آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘پھر قربانی کرو، اور اپنی اسی حالت پر احرام جاری رکھو۔‘‘ (1)","",{"k":"(1) البخاری (1557، 1558، 2505، 2506)، مسلم (1216)۔","f":"۱۔ صحابہ کرام رضی اللہ عنہم یہ بات سمجھتے تھے کہ تمام اعمال کی قبولیت کا دارومدار اتباع نبوی صلی اللہ علیہ وسلم پر ہے اسی لیے سیدنا علی رضی اللہ عنہ نے اتباع نبوی کے جذبہ میں اپنے احرام میں نبی صلی اللہ علیہ وسلم کے احرام کی نیت فرمائی۔\n۲۔ کسی دوسرے انسان کی نیت پر احرام باندھنا جائز ہے جیسا کہ سیدنا علی رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کی نیت پر احرام باندھا۔\n۳۔ اگر انسان کے پاس قربانی کا جانور موجود ہو تو حج قران ادا کرنا چاہیے اگر نہ ہو تو حج تمتع کرنا چاہیے۔\n۴۔ حج قران ادا کرنے والا ابتداء سے مناسک حج ادا کرنے تک حالت احرام ہی میں رہے گا۔"}],[799,"جابر رضی اللہ عنہ سے روایت ہے۔ وہ نبی صلی اللہ علیہ وسلم کے حج کے متعلق بیان کرتے ہیں۔ انہوں نے فرمایا: ہم نبی صلی اللہ علیہ وسلم کے ساتھ نکلے، یہاں تک کہ جب ہم بیداء مقام پر تھے تو میں نے اپنے آگے، دائیں، بائیں اور پیچھے تاحد نگاہ سوار اور پیادے دیکھے۔ ہر ایک یہ چاہتا تھا کہ وہ اس (حج) کو مکمل کرے۔ اور ہر کوئی اس کوشش میں تھا کہ اسی طرح کہے جس طرح رسول اللہ صلی اللہ علیہ وسلم فرما رہے ہیں۔ ہماری حج کے علاوہ کوئی اور نیت نہ تھی اور نہ ہم اس کے علاوہ کچھ جانتے تھے۔ اور نہ ہم حج کے مہینوں میں عمرہ کے متعلق جانتے تھے۔ اور جب ہم طواف کے بعد مروہ کے پاس تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے لوگو! جس کے پاس قربانی نہیں وہ احرام کھول دے اور اس احرام حج کو عمرہ بنا لے (یعنی طواف، سعی تو ہو چکی اور عمرہ کے افعال بھی پورے ہو گئے) اگر جو بات بعد میں میرے علم میں آئی ہے پہلے آجاتی تو میں قربانی نہ لاتا۔‘‘ تو جن کے پاس قربانی نہ تھی انہوں نے احرام کھول دیا۔ (1)","",{"k":"(1) مسلم (1218)۔"}],[800,"اسماء بنت ابی بکر رضی اللہ عنہا سے روایت ہے بیان فرماتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (حج کے لیے) نکلے تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس کے پاس قربانی (نہیں) ہے وہ حلال ہو جائے۔‘‘ اور میرے پاس قربانی نہ تھی تو میں نے احرام کھول دیا اور زبیر رضی اللہ عنہ کے پاس قربانی تھی انہوں نے احرام نہ کھولا۔ (1)","",{"k":"(1) مسلم (1236)۔","f":"۱۔ حجة الوداع کے موقع پر نبی صلی اللہ علیہ وسلم کے ساتھ صحابہ کرام رضی اللہ عنہم کا جم غفیر تھا اور تمام صحابہ اتباع نبوی کے جذبہ سے سرشار آپ صلی اللہ علیہ وسلم کی اقتدار کے خواہش مند تھے۔ معلوم ہوا حج کے لیے پیدل اور سوار ہو کر جانا دونوں طرح درست ہے۔\n۲۔ حج کی نیت کو فسخ کر کے عمرہ بنا دینا جائز ہے۔\n۳۔ جس کے پاس قربانی کا جانور ہو وہ حج تمتع نہیں کر سکتا۔\n۴۔ نبی صلی اللہ علیہ وسلم نے حج قران کیا اور تمتع کی تمنا فرمائی لہذا حج تمتع افضل ہے کیونکہ نبی صلی اللہ علیہ وسلم صرف افضل عمل کی ہی تمنا کر سکتے ہیں۔\n۵۔ صحابہ کرام رضی اللہ عنہم نبی صلی اللہ علیہ وسلم کے سچے متبعین تھے کہ نبی صلی اللہ علیہ وسلم نے اپنے ساتھ قربانی نہ لانے والوں کو احرام کھولنے کا حکم دیا تو سب اس پر بلا چوں چراں عمل پیرا ہو گئے۔\n۶۔ نبی صلی اللہ علیہ وسلم عالم الغیب نہیں ہیں لہذا نبی صلی اللہ علیہ وسلم کے عالم الغیب ہونے کا عقیدہ باطل ہے۔\n۷۔ نبی صلی اللہ علیہ وسلم مدینہ سے اپنے ساتھ قربانی کا جانور لائے تھے۔"}],[801,"عائشہ رضی اللہ عنہا سے روایت ہے بیان فرماتی ہیں کہ ابھی ذی قعدہ کے پانچ دن باقی تھے کہ ہم نبی صلی اللہ علیہ وسلم کے ساتھ حج کے ارادہ سے نکلے۔ جب ہم مقام سرف یا اس کے قریب تھے تو نبی صلی اللہ علیہ وسلم نے حکم دیا، جس کے پاس قربانی نہیں وہ اپنے احرام (حج) کو عمرہ بنالے۔ اور جب ہم منی میں تھے میرے پاس گائے کا گوشت آیا میں نے کہا یہ کیسا گوشت ہے؟ کہا: کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں کی طرف سے قربانی کی ہے۔ یحییٰ نے کہا کہ میں نے یہ حدیث قاسم بن محمد سے بیان کی تو انہوں نے کہا عمرہ تیرے پاس اللہ کی قسم۔ حدیث اپنی اصل شکل میں لائی ہیں۔ (1)","",{"k":"(1) البخاری (1720)، مسلم (1211)۔"}],[802,"ایک دوسری سند سے عمرہ اور قاسم دونوں سے سفیان رحمہ اللہ کی سند جیسی بغیر معنی کی مخالفت کے یہی حدیث مروی ہے۔ (1)","",{"k":"(1) البخاری (1709)۔","f":"۱۔ معلوم ہوا نبی صلی اللہ علیہ وسلم نے حج کے موقع پر امہات المومنین رضی اللہ عنہن کی طرف سے مشترکہ طور پر ایک گائے ذبح کی تھی۔\n۲۔ ایک گھر والوں کی طرف سے گائے کی قربانی درست ہے۔\n۳۔ حج کے موقع پر اپنی قربانی کا گوشت بھی کھانا چاہیے۔"}],[803,"طاوس کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ سے نکلے تو آپ حج یا عمرہ کا نام نہیں لیتے تھے بلکہ آپ وحی کا انتظار فرمارہے تھے۔ جب آپ صفا اور مروہ کے درمیان تھے تو اس وقت وحی نازل ہوئی۔ تو آپ صلی اللہ علیہ وسلم نے ان صحابہ رضی اللہ عنہم کو حکم دیا جنہوں نے احرام (حج کا) باندھا ہوا تھا اور ان کے پاس قربانی نہ تھی کہ وہ اس کو عمرہ بنا لیں۔ اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر وہ بات جو مجھے بعد میں معلوم ہوئی پہلے معلوم ہو جاتی تو میں قربانی نہ لاتا۔ لیکن میں نے سر کے بال چپکا لیے اور قربانی ہانک لایا ہوں۔ اب میں قربانی کے بغیر حلال نہیں ہو سکتا۔’’سراقہ بن مالک رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کی طرف کھڑے ہوئے اور کہا، آپ ہمارے لیے ایک ایسی قوم کا فیصلہ کریں گویا جو آج ہی پیدا ہوئی کیا ہمارا یہ عمرہ خاص صرف اسی سال کے لیے ہے یا ہمیشہ کے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘بلکہ ہمیشہ کے لیے ہے۔‘‘ اب عمرہ (ایام) حج میں قیامت کے دن تک کے لیے داخل ہو گیا ہے۔ طاوس نے کہا (مکہ میں) علی رضی اللہ عنہ یمن سے تشریف لائے تو ان سے نبی صلی اللہ علیہ وسلم نے پوچھا: آپ نے کس نیت سے احرام باندھا ہے؟ میسرہ اور ہشام بن حجیرہ میں سے ایک نے طاوس سے روایت کیا کہ علی رضی اللہ عنہ نے کہا: نبی صلی اللہ علیہ وسلم کے احرام کا (یعنی جس نیت سے آپ صلی اللہ علیہ وسلم نے باندھا ہے) اور دوسرے نے کہا کہ میں حاضر ہوں نبی صلی اللہ علیہ وسلم کے حج کے ساتھ۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (5/6)، المعرفة السنن والآثار لہ (2683)۔","f":"۱۔ عہد جاہلیت میں ایام حج میں عمرہ معیوب سمجھا جاتا تھا، اسلام نے ان کے اس غلط خیال کی اصلاح فرمائی اور اعلان کیا کہ حج کے مہینوں میں بھی عمرہ جائز ہے۔\n۲۔ دینی امور میں علماء سے راہنمائی لینا مستحسن عمل ہے۔\n۳۔ اشکالات کے ازالہ کے لیے سوالات کرنا درست ہے۔\n۴۔ نبی صلی اللہ علیہ وسلم کی ہدایات قیامت تک کے لیے ہیں۔ اور آپ کی ذات ہی مرکز ہدایت ہے۔"}],[804,"جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نو برس تک مدینہ میں رہے اور آپ نے حج نہیں کیا پھر (دسویں سال) لوگوں میں حج کے لیے منادی کرائی۔ لوگ آپ صلی اللہ علیہ وسلم کے ساتھ نکلنے کے لیے مدینہ میں آنے لگے۔ رسول اللہ صلی اللہ علیہ وسلم (حج کے لیے) چلے اور ہم بھی آپ کے ساتھ چلے، ہم صرف حج کا ارادہ رکھتے تھے اور اسی غرض سے نکلے تھے۔ اور رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے اور آپ پر قرآن اترتا تھا اور آپ اس کی حقیقت کو خوب جانتے تھے اور آپ صلی اللہ علیہ وسلم اسی طرح کرتے تھے جس طرح آپ کو حکم ہوتا تھا۔ جب ہم مکہ آپہنچے تو جب رسول اللہ صلی اللہ علیہ وسلم نے بیت اللہ کا طواف اور صفا، مروہ کی سعی کر لی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جس کے پاس قربانی نہیں وہ اس کو عمرہ بنالے اور اگر وہ بات جو مجھے بعد میں معلوم ہوئی پہلے ہو جاتی تو میں قربانی نہ لاتا اور اس کو عمرہ بنالیتا۔‘‘ (1)","",{"k":"(1) مسلم (1218)۔","f":"۱۔ حج فتح مکہ کے بعد ۹ھ میں فرض ہوا اور مسلمانوں نے پہلا حج سیدنا ابوبکر رضی اللہ عنہ کی قیادت میں ادا کیا پھر اگلے سال کم و بیش ایک لاکھ کے قریب صحابہ کرام رضی اللہ عنہم نے نبی صلی اللہ علیہ وسلم کی اقتداء میں فریضہ حج ادا کیا جسے حجة الوداع کہا جاتا ہے۔\n۲۔ نبی صلی اللہ علیہ وسلم وحی کی اتباع کرتے اور صحابہ کرام رضی اللہ عنہم بھی نبی صلی اللہ علیہ وسلم کی اسوہ نبوی پر عمل پیرا ہوتے تھے۔\n۳۔ قرآن کی بہترین تفسیر نبی صلی اللہ علیہ وسلم کے اقوال و افعال اور تقریرات ہیں۔ مزید دیکھئے فوائد حدیث نمبر ۷۹۹۔"}],[805,"طاوس کہتے ہیں کہ نبی صلی اللہ علیہ وسلم نکلے تو آپ حج اور عمرہ کا نام نہیں لے رہے تھے بلکہ آپ وحی کے منتظر تھے۔ طاوس نے کہا جب آپ صفا اور مروہ کے درمیان چکر لگا رہے تھے تو آپ پر وحی نازل ہوئی۔ آپ نے اپنے صحابہ (رضی اللہ عنہم) کو حکم دیا کہ جس نے ان میں سے حج کے لیے احرام باندھا ہے اور اس کے پاس قربانی نہیں تو وہ اسے عمرہ بنالے۔ پھر فرمایا: ’’اگر مجھے پہلے معلوم ہو جاتا جو بعد میں ہوا تو میں قربانی نہ لاتا، لیکن میں نے اپنے سر کے بال چپکا لیے ہیں اور قربانی ساتھ ہانک لایا ہوں، اب میرے لیے قربانی کیے بغیر حلال ہونا درست نہیں ہے۔’’پھر سراقہ بن مالک رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کی طرف کھڑے ہوئے اور عرض کی اے اللہ کے رسول! آپ ہمارے بارے میں ایک آج کے دن جنم لینے والی قوم کی طرح فیصلہ کریں، یہ حج کو عمرہ کر ڈالنا ہمارے اسی سال کے لیے خاص ہے یا ہمیشہ کے لیے اس کی اجازت ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘ہمیشہ کے لیے اجازت ہے، عمرہ قیامت تک کے لیے (ایام) حج میں داخل ہو گیا۔’’اس نے کہا کہ علی رضی اللہ عنہ (مکہ میں) یمن سے داخل ہوئے تو نبی صلی اللہ علیہ وسلم نے پوچھا:‘‘آپ نے کس چیز کا احرام باندھا؟‘‘ ابن طاوس اور ابراہیم بن میسرہ میں سے ایک نے کہا: میں نے احرام باندھ کر تلبیہ کہا نبی صلی اللہ علیہ وسلم کے احرام کی طرح، اور دوسرے نے کہا میں نے حج کا تلبیہ کہا نبی صلی اللہ علیہ وسلم کے حج کی طرح۔ (1)","",{"k":"(1) انظر الحدیث السابق برقم (803)","f":"دیکھئے فوائد حدیث نمبر ۸۰۳۔"}],[806,"عبداللہ بن عمر رضی اللہ عنہما حفصہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے کہا اے اللہ کے رسول (صلی اللہ علیہ وسلم)! لوگوں کی کیا حالت ہے کہ انہوں نے عمرہ کر کے احرام کھول دیا اور آپ نے عمرہ فرما کر احرام نہیں کھولا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے اپنے سر کے بالوں کو چپکایا ہے اور اپنی قربانی کے گلے میں ہار ڈالا ہے سو میں اس وقت تک احرام نہ کھولوں گا جب تک کہ قربانی ذبح نہ کرلوں۔‘‘ (1)","",{"k":"(1) البخاری (1566)، مسلم (1329)۔","f":"۱۔ جن صحابہ کے پاس قربانی کے جانور نہیں تھے انہوں نے تو احرام کھول دیے چونکہ نبی صلی اللہ علیہ وسلم کے پاس قربانی کا جانور تھا اس لیے آپ نے احرام نہ کھولا۔ ۲۔ بالوں کو لیپ کرنا جائز ہے۔ ۲۔ قارن قربانی کے بعد احرام کھولے گا۔ ۴۔ معاملات کی تحقیق کرنا درست ہے۔"}],[807,"محمد بن عبداللہ بن حارث بن نوفل رضی اللہ عنہ سے روایت ہے انہوں نے سعد بن ابی وقاص اور ضحاک بن قیس رضی اللہ عنہما کو جس سال معاویہ بن ابی سفیان رضی اللہ عنہ حج کے لیے آئے، آپس میں حج تمتع کے متعلق باتیں کرتے سنا تو ضحاک نے کہا (حج تمتع) صرف وہی کرے گا جس کو اللہ کی شریعت کا علم نہیں ہے۔ سعد رضی اللہ عنہ نے فرمایا: اے بھتیجے تو نے اچھا نہیں کہا، ضحاک نے کہا بے شک عمر رضی اللہ عنہ نے اس سے منع کیا، تو سعد رضی اللہ عنہ نے فرمایا: حج تمتع رسول اللہ صلی اللہ علیہ وسلم نے کیا اور ہم نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ (حج تمتع) کیا۔ (1)","",{"k":"(1) الترمذی (823)، وقال ’’صحیح‘‘، النسائی (2735)۔","f":"۱۔ حج تمتع: اس حج میں حاجی حضرات میقات سے صرف عمرہ کا احرام باندھتے ہیں اور مکہ مکرمہ مناسک عمرہ ادا کرنے کے بعد احرام کھول دیتے ہیں پھر آٹھ ذوالحجہ کو مکہ ہی سے دوبارہ احرام باندھ کر مناسک حج ادا کرتے ہیں۔ ۲۔ سیدنا عمر رضی اللہ عنہ حج تمتع کے قائل تھے لیکن ان کا لوگوں کو حج تمتع سے منع کرنا ایک خاص سبب سے تھا۔ جیسا کہ سیدنا ابو موسیٰ اشعری رضی اللہ عنہ فرماتے ہیں مجھے پتہ چلا کہ سیدنا عمر رضی اللہ عنہ لوگوں کو حج تمتع سے منع کرتے ہیں تو میں نے ان سے ملاقات کر کے اس سے متعلق دریافت فرمایا تو سیدنا عمر رضی اللہ عنہ نے فرمایا: «قد علمت ان رسول اللہ صلی اللہ علیہ وسلم قد فعلہ، واصحابہ ولکن کرھت ان یظلوا معرسین بھن فی الأراک، ثم یروحون فی الحج تقطر رؤسھم» ’’مجھے معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ رضی اللہ عنہم نے یہ (تمتع) کیا ہے لیکن مجھے یہ بات ناپسند ہے کہ لوگ رات درختوں تلے عورتوں سے خلوت اختیار کریں پھر صبح حج کے لیے اس حالت میں روانہ ہوں کہ ان کے سروں سے (پانی کے) قطرے ٹپک رہے ہوں۔‘‘ (صحیح مسلم، رقم: ۱۲۲۲) ۳۔ معلوم ہوا سیدنا عمر رضی اللہ عنہ نے اجتہاد کر کے حج تمتع سے منع فرمایا جبکہ ان کے بیٹے سیدنا عبداللہ رضی اللہ عنہ نے نص صریح اور صحیح احادیث پر عمل کرتے ہوئے ان کی مخالفت کی اور حج تمتع کو جائز قرار دیا۔ (دیکھئے: سنن ترمذی، رقم: ۸۲۴ وقال حسن صحیح) ۴۔ جب صحیح احادیث کے مقابل خلیفہ راشد سیدنا عمر رضی اللہ عنہ کی پیروی درست نہیں تو امام یا مجتہد احادیث کے خلاف قابل اقتداء کیسے ہو سکتے ہیں؟ ۵۔ رسول اللہ صلی اللہ علیہ وسلم نے حج قران ادا کیا تھا جبکہ صحابہ رضی اللہ عنہم نے آپ کے حکم سے حج تمتع کیا۔ سیدنا سعد بن ابی وقاص رضی اللہ عنہ کا یہ فرمانا کہ رسول اللہ صلی اللہ علیہ وسلم نے تمتع کیا آپ کے حکم کو عمل کے برابر قرار دینا ہے۔ واللہ اعلم۔ ۶۔ اگر کسی شخص کو دلیل معلوم نہ ہو تو اس کا احسن انداز سے دلیل کے ساتھ رد کرنا چاہیے۔ یہی سلف کا طریقہ کار رہا ہے۔"}],[808,"ابن عمر رضی اللہ عنہما سے مروی ہے انہوں نے فرمایا: میں حج سے پہلے عمرہ کروں اور قربانی دوں یہ بات مجھے اس بات سے زیادہ پسند ہے کہ میں ذی الحجہ میں حج کے بعد عمرہ کروں۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (4/345)، المعرفة السنن والآثار لہ (2704)۔","f":"۱۔ حج تمتع کرنے والا دس ذوالحجہ کو قربانی دے گا اگر اس کے پاس قربانی کی طاقت نہیں تو پھر بطور فدیہ دس روزے رکھے گا جن میں سے تین ایام حج میں رکھنا ضروری ہیں باقی سات اپنے ساتھ گھر آ کر رکھے گا۔ ۲۔ ایام حج میں عمرہ مشروع ہے لیکن حج سے پہلے عمرہ ادا کر کے حج کو تمتع بنا لینا زیادہ فضیلت کا باعث ہے اسی لیے سیدنا عبداللہ رضی اللہ عنہ فرماتے ہیں حج کے بعد ذوالحجہ میں عمرہ کرنے سے مجھے پہلے عمرہ کرنا زیادہ محبوب ہے۔"}],[809,"ابن عباس رضی اللہ عنہما سے مروی ہے کہ ان سے پوچھا گیا آپ حج سے پہلے عمرہ کی ادائیگی کے متعلق کیا کہتے ہیں جبکہ اللہ تعالیٰ فرماتے ہیں ’’اور تم اللہ کے لیے حج اور عمرہ کو مکمل کرو۔‘‘ تو ابن عباس رضی اللہ عنہما نے کہا تم کس طرح پڑھتے ہو کہ کیا قرض کی ادائیگی وصیت پر عمل کرنے سے پہلے ہے یا وصیت پر عمل قرض کی ادائیگی سے پہلے ہوگا؟ انہوں نے کہا: وصیت پر عمل قرض کی ادائیگی سے پہلے ہے۔ آپ رضی اللہ عنہ نے فرمایا: ان دونوں میں سے تم کس سے ابتداء کرو گے؟ تو انہوں نے کہا: قرض سے (یعنی پہلے قرض دیں گے) آپ نے فرمایا: تو یہی ہے وہ۔ امام شافعی رحمہ اللہ نے فرمایا: یعنی حج سے پہلے عمرہ کرنا جائز ہے۔ (1)","",{"k":"(1) فی اسنادہ مقال (7288)، البیہقی (4/351)۔"}],[810,"نافع رحمہ اللہ سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہما نے فتنہ والے سال حج کا ارادہ کیا، احرام باندھا پھر غور کیا اور فرمایا: حج اور عمرہ تو دونوں ایک ہی ہیں، میں تمہیں گواہ بناتا ہوں کہ میں نے حج کے ساتھ عمرہ کو واجب کر لیا ہے۔ (1)","",{"k":"(1) البخاری (1639، 1640)، مسلم (1230)۔","f":"۱۔ حج قران: میقات سے حج و عمرہ دونوں کی نیت سے احرام باندھ کر مکہ مکرمہ جانا اور تمام مناسک حج کی ادائیگی تک احرام نہ کھولنا ’’حج قران‘‘ ہے۔ حج قران کے لیے اپنے وطن یا میقات سے قربانی ساتھ لے کر جانا ضروری ہے۔ ۲۔ سیدنا ابن عمر رضی اللہ عنہما نے یہ احرام ۷۳ھ کو باندھا جب حجاج سیدنا عبداللہ بن زبیر رضی اللہ عنہما کے مقابلے میں لڑنے کے لیے آیا تھا۔ ۳۔ ابن عمر رضی اللہ عنہما نے آغاز میں عمرہ کی نیت سے احرام باندھا تھا اور بعد میں حج و عمرہ دونوں یعنی قران کی نیت کر لی تھی۔ ۴۔ اگر چہ راستہ پر خطر ہو پھر بھی حج و عمرہ کی نیت سے بیت اللہ کا سفر کرنا جائز ہے۔ ۵۔ اگر انسان کو کسی عذر کی بنا پر بیت اللہ سے روک دیا جائے تو وہ ایک بکری بطور فدیہ دے گا۔ واللہ اعلم۔ ۶۔ حج قران میں ایک ہی طواف اور ایک ہی سعی حج و عمرہ کی طرف سے کافی ہے۔"}],[811,"عائشہ رضی اللہ عنہا سے روایت ہے انہوں نے فرمایا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حجتہ الوداع والے سال نکلے تو ہم میں سے بعض وہ تھے جنہوں نے حج کا احرام باندھا، اور ہم میں سے بعض نے عمرہ کا احرام باندھا اور ہم میں سے بعض نے حج اور عمرہ کو اکٹھا کیا، اور میں ان لوگوں میں سے تھی جنہوں نے عمرہ کا احرام باندھا تھا۔ (1)","",{"k":"(1) البخاری (1556)، مسلم (1211)۔","f":"۱۔ نبی صلی اللہ علیہ وسلم کے ساتھ حجتہ الوداع کے موقع پر صحابہ کرام رضی اللہ عنہم مختلف نیتوں سے احرام باندھ کر شریک ہوئے تھے۔ بعض صرف حج، بعض صرف عمرہ جبکہ بعض حج و عمرہ کی نیت سے آئے تھے۔ ۲۔ معلوم ہوا حجتہ الوداع کے موقع پر سیدہ عائشہ رضی اللہ عنہا نے صرف عمرہ کی نیت سے احرام باندھا تھا۔"}],[812,"عروہ رحمہ اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ضباعہ بنت زبیر کے پاس سے گزرے تو آپ نے فرمایا: ’’کیا تیرا حج کا ارادہ نہیں؟’’تو انہوں نے کہا میں (بیماری کے بارے میں) شک کرنے والی ہوں۔ آپ صلی اللہ علیہ وسلم نے اسے کہا:‘‘حج کا احرام باندھ لو اور شرط لگا لو کہ میں وہاں حلال ہو جاؤں گی جہاں مجھے (مرض کی وجہ سے) تو روک لے گا۔‘‘ (1)","",{"k":"(1) حدیث صحیح فقد صح موصولا: البخاری (5089)، مسلم (1208)۔","f":"۱۔ بیمار آدمی حج و عمرہ کی نیت سے سفر کر سکتا ہے۔ ۲۔ اگر بیماری بڑھنے کا خدشہ ہو تو احرام باندھتے وقت شرط عائد کر لے کہ مجھے جہاں رکاوٹ پیش آئے گی میں وہیں احرام کھول دوں گا۔ ۳۔ اگر مشروط احرام سے حج یا عمرہ کی ادائیگی ہو جائے تو اس فریضہ کے ادا کرنے والے کو پورا پورا اجر و ثواب ملے گا۔"}],[813,"کہتے ہیں مجھے عائشہ رضی اللہ عنہا نے کہا کیا جب تو حج کرے تو استثناء کرتا ہے؟ عروہ کہتے ہیں میں نے کہا میں کیا کہوں؟ عائشہ رضی اللہ عنہا نے فرمایا: کہہ اے اللہ میں نے حج کا ارادہ کیا اور اسی کے لیے قصد کیا، اگر تو میرے لیے آسان بنا دے تو وہ حج ہے اور اگر مجھے کوئی روکنے والا روک لے تو یہ عمرہ ہے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/223)، المعرفة السنن والآثار لہ (3262)۔","f":"۱۔ یہ حدیث بھی سابقہ حدیث میں بیان شدہ مسئلہ کی مؤید ہے کہ احرام باندھتے وقت شرط عائد کرنا درست ہے۔"}],[814,"نافع رحمہ اللہ سے روایت ہے وہ ابن عمر رضی اللہ عنہما سے کہ وہ فتنہ کے زمانہ میں عمرہ کے لیے مکہ کی طرف نکلے، اور فرمایا: اگر مجھے بیت اللہ پہنچنے سے روک دیا گیا تو ہم اسی طرح کریں گے جس طرح ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کیا تھا۔ امام شافعی رحمہ اللہ نے فرمایا، یعنی ہم اس طرح حلال ہو جائیں گے جس طرح ہم صلح حدیبیہ والے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حلال ہو گئے تھے۔ (1)","",{"k":"(1) البخاری (1806)، مسلم (1230)۔","f":"۱۔ نبی اکرم صلی اللہ علیہ وسلم کو مشرکین مکہ نے ۶ھ میں حدیبیہ کے مقام پر کعبتہ اللہ جانے سے روک دیا تو آپ نے اسی جگہ احرام کھول کر جانوروں کو قربان فرما دیا۔ ابن عمر رضی اللہ عنہما بھی فرماتے ہیں اگر مجھے بھی روک دیا گیا تو میں رسول اللہ صلی اللہ علیہ وسلم کی سنت کے مطابق عمل کروں گا۔ مگر سیدنا عبداللہ بن عمر رضی اللہ عنہما کے ساتھ ایسا نہ ہوا بلکہ انہوں نے فتنہ و فساد سے قبل جملہ ارکان حج ادا فرما لیے تھے۔ ۲۔ ابن عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم کی سنتوں سے محبت رکھنے والے اور ان کی اتباع کرنے والے تھے۔"}],[815,"عروہ رحمہ اللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ضباعہ کو حکم دیا اور فرمایا: ’’کیا تو حج نہیں کرنا چاہتی؟’’اس نے کہا میں (بیماری کا) شک کرنے والی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:‘‘حج کا احرام باندھ لو اور شرط لگا لو کہ میں وہاں حلال ہو جاؤں گی جہاں تو مجھے (مرض کی وجہ سے) روک دے گا۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (815)۔","f":"۱۔ دیکھئے فوائد حدیث نمبر: ۸۱۲۔"}],[816,"عروہ رحمہ اللہ سے روایت ہے بیان کرتے ہیں کہ مجھ سے عائشہ رضی اللہ عنہا نے کہا اے بھانجے کیا تو جب حج کا ارادہ کرتا ہے تو استثناء بھی کرتا ہے؟ میں نے کہا، کیا کہوں؟ عائشہ رضی اللہ عنہا نے فرمایا: ’’کہہ اے اللہ میں نے حج کا ارادہ کیا، اور اس کے لیے قصد کیا، اگر تو میرے لیے آسانی پیدا فرما دے تو وہ حج ہے اور اگر کوئی روکنے والا مجھے روک دے تو وہ عمرہ ہے۔‘‘ (1)","",{"k":"(1) انظر الحدیث السابق برقم (813)۔","f":"۱۔ دیکھئے فوائد حدیث نمبر: ۸۱۳۔"}],[817,"جابر بن عبداللہ رضی اللہ عنہما بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی بھی اپنے تلبیہ میں حج اور عمرہ کا نام نہیں لیا۔ (1)","",{"k":"(1) اسنادة ضعیف جدا، لضعف شیخ الشافعی: البیہقی (5/40)، المعرفة السنن والآثار لہ (2717)۔"}],[818,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا تلبیہ یہ تھا: ’’اے اللہ! میں حاضر ہوں، میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں، بے شک تمام تعریفیں اور نعمتیں تیرے لیے ہیں اور بادشاہی تیرے لیے ہے تیرا کوئی شریک نہیں۔‘‘ نافع نے کہا کہ عبداللہ بن عمر رضی اللہ عنہما اس میں ان الفاظ کا اضافہ کرتے، میں حاضر ہوں، میں حاضر ہوں، اور تیری عبادت سے موافقت کرتا ہوں، اور (ہر قسم) خیر تیرے ہاتھوں میں ہے۔ (ہر قسم کی) رغبت اور عمل تیری طرف ہے (یعنی تیرے لیے ہے۔) (1)","",{"k":"(1) البخاری (1549)، مسلم (1184)۔","f":"۱۔ تلبیہ سنت رسول اور بہت بڑی نیکی ہے جو حج کے عظیم مظاہر میں سے ایک ہے۔ ۲۔ تلبیہ کے مختلف الفاظ صحیح احادیث میں مروی ہیں ان میں سے کوئی سے الفاظ بھی اختیار کیے جا سکتے ہیں۔ ۳۔ حج و عمرہ کے موقع پر تلبیہ پکار کر آدمی عاجزی و انکساری سے اس بات کا اظہار کرتا ہے کہ اے اللہ میں تیری عبادت پر قائم ہوں اور تیرے بلانے پر تیرے گھر میں حاضر ہوا ہوں۔ اور اس راہ میں آنے والی مشکلات کے لیے تیار ہوں۔ ۴۔ تلبیہ کے عظیم الشان کلمات اللہ کی توحید کے اعلان پر مشتمل ہیں جن کے اظہار سے انسان اللہ کے معبود برحق لا شریک ہونے کے ساتھ اسی اکیلے کے خالق و مالک ہونے کا اعلان کرتا ہے۔ ۵۔ نبی صلی اللہ علیہ وسلم کی موجودگی میں مختلف صحابہ نے تلبیہ کے الفاظ میں اضافہ کیا لیکن آپ خاموش رہے۔ دیکھئے (سنن ابو داؤد، رقم: ۱۸۱۳) ۶۔ تلبیہ کے الفاظ میں افضل یہی ہے کہ نبی صلی اللہ علیہ وسلم کے ادا کیے ہوئے الفاظ ہی پر اکتفا کیا جائے۔ ۷۔ ابن عمر رضی اللہ عنہما کے الفاظ سے معلوم ہوتا ہے کہ حج و عمرہ عظیم سعادت ہے۔ ۸۔ اعمال کی قبولیت اللہ رب العزت کے ہاتھ ہیں۔ کما یلیق بشانہ وجلالہ۔"}],[819,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے توحید کے ساتھ یہ تلبیہ کہا: میں حاضر ہوں اے اللہ! میں حاضر ہوں۔ میں حاضر ہوں تیرا کوئی شریک نہیں میں حاضر ہوں، بے شک تمام تعریفیں اور نعمتیں تیرے لیے ہیں اور تیرے لیے ہی بادشاہت ہے تیرا کوئی شریک نہیں۔ (1)","",{"k":"(1) مسلم (1218)۔","f":"دیکھئے فوائد حدیث نمبر: ۸۱۸۔"}],[820,"ابوہریرہ رضی اللہ عنہ سے روایت ہے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے تلبیہ کے الفاظ میں سے یہ بھی تھے، میں حاضر ہوں اے سچے معبود میں حاضر ہوں۔ (1)","",{"k":"(1) النسائی (2753)، ابن ماجة (2920)، وصححہ ابن خزیمة (2623)، الحاکم (1/449، 450)، ووافقہ الذھبی۔","f":"تلبیہ کے سلسلہ میں اس روایت میں موجود الفاظ مختصر ترین ہیں جو نبی صلی اللہ علیہ وسلم سے ثابت ہیں لہذا جو آدمی کسی وجہ سے تلبیہ ’’لبیک اللھم لبیک..............‘‘ کے الفاظ یاد نہ کر سکے اس کو تین الفاظ پر مبنی اس مختصر سے تلبیہ کو یاد کر لینا چاہیے۔"}],[821,"مجاہد رحمہ اللہ سے روایت ہے بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے تلبیہ سے ظاہر فرماتے: ’’میں حاضر ہوں، اے اللہ! میں حاضر ہوں، میں حاضر ہوں تیرا کوئی شریک نہیں۔ میں حاضر ہوں، بے شک تمام تعریفیں اور نعمتیں تیرے لیے ہیں اور تیری ہی بادشاہی ہے تیرا کوئی شریک نہیں۔‘‘ فرمایا حتی کہ ایک دن جب لوگ واپس آ رہے تھے تو گویا اس کے الفاظ نے آپ کو خوش کر دیا، تو آپ نے اس میں یہ الفاظ زیادہ کر دیئے۔ میں حاضر ہوں، اصل زندگی آخرت کی زندگی ہے۔ ابن جریج نے کہا: میرے خیال میں یہ عرفہ کا دن تھا۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (5/45)، المعرفة السنن والآثار لہ (2813)۔"}],[822,"عبداللہ بن ابی سلمہ سے روایت ہے وہ بیان کرتے ہیں کہ سعد بن ابی وقاص رضی اللہ عنہ نے اپنے بھتیجوں میں سے کسی کو تلبیہ کہتے سنا وہ کہہ رہا ہے، اے سیڑھیوں والے، تو سعد رضی اللہ عنہ نے کہا کیا سیڑھیاں؟ بے شک وہ سیڑھیوں والا ہے، مگر ہم رسول اللہ صلی اللہ علیہ وسلم کے عہد میں اس طرح تلبیہ نہیں کہتے تھے۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی (5/45)، المعرفة السنن والآثار لہ (2814)، احمد (1/172)، ابن ابی شیبة (13467)۔","f":"۱۔ معلوم ہوا سعد بن ابی وقاص رضی اللہ عنہ کا موقف یہ تھا کہ تلبیہ کے ماثور و مسنون الفاظ کے علاوہ اور الفاظ کا پڑھنا درست نہیں۔ جبکہ یہی ’’ذو المعارج‘‘ کے الفاظ نبی صلی اللہ علیہ وسلم کے سامنے پڑھے گئے اور آپ نے خاموشی اختیار کی۔ (دیکھئے: سنن ابی داؤد، رقم: ۱۸۱۳) ۲۔ تلبیہ کے الفاظ میں کمی بیشی مباح ہے لیکن نبی صلی اللہ علیہ وسلم کے الفاظ کو اختیار کرنا افضل و بہتر ہے۔ (تفصیل کے لیے دیکھئے فوائد حدیث نمبر ۸۱۸)"}],[823,"محمد بن ابو بکر ثقفی سے روایت ہے کہ انہوں نے انس بن مالک رضی اللہ عنہما سے پوچھا جبکہ وہ دونوں صبح کو منی سے عرفات جا رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ آپ لوگ آج کے دن کیا کرتے تھے؟ انس رضی اللہ عنہ نے فرمایا: کوئی ہم میں سے لبیک پکار رہا ہوتا تو اس پر بھی کوئی اعتراض نہ کرتا اور کوئی تکبیر کہتا تو اس پر بھی کوئی اعتراض نہ کرتا۔ (1)","",{"k":"(1) البخاری (970)، مسلم (1285)۔","f":"۱۔ معلوم ہوا 9 ذوالحجہ کو منی سے عرفہ کی طرف جاتے ہوئے تکبیرات یا لبیک اسی طرح کچھ راستہ تکبیرات اور کچھ راستہ لبیک پکارنا، دونوں طرح درست ہے۔"}],[824,"سائب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرے پاس جبرائیل آئے اور مجھے حکم دیا کہ میں اپنے صحابہ رضی اللہ عنہم یا جو میرے ساتھ ہیں ان کو حکم دوں کہ وہ تکبیر یا تلبیہ کے وقت اپنی آوازوں کو بلند کریں، وہ ان دونوں میں سے ایک کا ارادہ کرتے ہیں۔‘‘ (1)","",{"k":"(1) الترمذی (829)، وقال: ’’حسنٌ صحیحٌ‘‘، النسائی (2754)، ابن ماجہ (2922)، وصححہ ابن خزیمة (2625، 2627)، ابن الجارود (434)، الحاکم (1/450)۔","f":"۱۔ معلوم ہوا تلبیہ بلند آواز سے پڑھنا ضروری ہے۔\n۲۔ جس طرح جبریل امین قرآن کی صورت میں رسول اللہ صلی اللہ علیہ وسلم میں وحی لے کر آتے تھے اسی طرح بعض اوقات حکمت (حدیث، وحی غیر متلو) کی بھی وحی لاتے تھے۔\n۳۔ جس طرح قرآن منزل من اللہ ہے اور اس پر عمل فرض ہے اسی طرح حدیث مصطفیٰ صلی اللہ علیہ وسلم بھی منزل من اللہ اور واجب الاتباع ہے۔"}],[825,"محمد بن منکدر سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کثرت سے تلبیہ کہتے تھے۔ (1)","",{"k":"(1) اسنادة ضعیف، لضعف محمد بن ابی حمید ولإرسالہ: البیہقی فی المعرفة السنن والآثار (2803)۔"}],[826,"ابن عمر رضی اللہ عنہما سے روایت ہے کہ وہ سوار، پیدل اور لیٹے ہوئے بھی تلبیہ کہتے تھے۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی (5/43)، المعرفة السنن والآثار لہ (2804)۔","f":"۱۔ معلوم ہوا حج وعمرہ میں تلبیہ کے الفاظ بکثرت اور ہر حالت میں پڑھنے چاہئیں۔"}],[827,"خزیمہ بن ثابت رضی اللہ عنہ سے روایت ہے وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ جب تلبیہ سے فارغ ہوتے تو اللہ تعالیٰ سے اس کی خوشنودی اور جنت کا سوال کرتے، اور اس کی رحمت کے وسیلہ سے جہنم سے معافی مانگتے۔ (1)","",{"k":"(1) اسنادة ضعیف لضعف شیخ الشافعی: البیہقی (5/46)، المعرفة السنن والآثار لہ (2816)، البغوی (1866)، الدارقطنی (2/238)۔"}],[828,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے وہ بیان کرتے ہیں کہ مجھے فضل بن عباس رضی اللہ عنہما نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مزدلفہ سے واپسی پر انہیں منی تک اپنے پیچھے سوار کیا تھا، آپ برابر جمرہ (عقبہ) کی رمی تک لبیک پکارتے رہے۔ (1)","",{"k":"(1) البخاری (1685)، مسلم (1281)۔"}],[829,"ابن عباس رضی اللہ عنہما نے فرمایا کہ مجھے فضل بن عباس رضی اللہ عنہما نے بتایا کہ اسے نبی صلی اللہ علیہ وسلم نے مزدلفہ سے منی تک اپنے پیچھے بٹھایا تھا اور آپ جمرہ (عقبہ) کی رمی تک برابر لبیک کہتے رہے۔ (1)","",{"k":"(1) انظر الحدیث الذی قبلہ برقم: (828)"}],[830,"ایک اور سند سے فضل بن عباس رضی اللہ عنہما کے واسطے سے نبی صلی اللہ علیہ وسلم سے اسی طرح مروی ہے۔ (1)","",{"k":"(1) البخاری (1670)، مسلم (1281)۔","f":"۱۔ مذکورہ حدیث سے معلوم ہوا دوران حج جمرہ عقبی کو آخری کنکری مارنے کے بعد تلبیہ ختم ہو جائے گا۔\n۲۔ حجة الوداع کے موقع پر سیدنا فضل بن عباس رضی اللہ عنہما مزدلفہ سے منی تک نبی صلی اللہ علیہ وسلم کے ساتھ سواری پر سوار رہے۔\n۳۔ ایک جانور پر ایک دو افراد کا سوار ہونا درست ہے۔"}],[831,"ابن عباس رضی اللہ عنہ سے روایت ہے فرمایا کہ عمرہ کرنے والا تلبیہ کہے گا یہاں تک کہ وہ پیدل چلتے ہوئے یا بغیر پیدل چلے (سوار) طواف شروع کرے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی فی المعرفة السنن والآثار (2945)۔"}],[832,"مجاہد رحمہ اللہ سے روایت ہے کہ وہ ابن عباس رضی اللہ عنہما سے عمرہ کرنے والے کے متعلق مروی ہے کہ وہ تلبیہ کہے گا حتی کہ حجر اسود کو بوسہ دے۔ (1)","",{"k":"(1) اسنادة صحیح: ابوداود (1817)۔"}],[833,"ابن عباس رضی اللہ عنہما سے روایت انہوں نے فرمایا: عمرہ کرنے والا تلبیہ کہے گا یہاں تک کہ وہ طواف ہاتھ لگا کر یا بغیر ہاتھ لگائے شروع کرے۔ (1)","",{"k":"(1) صحیح موقوفاً وثبت مرفوعاً بسند صحیح: اخرجہ ابوداود (1817) موقوفاً۔ والترمذی (919)۔ مرفوعاً وقال ’’حدیث صحیح‘‘ وصححہ ابن خزیمة (2697)۔ وابن الجارود (451)۔","f":"۱۔ معلوم ہوا عمرہ کرنے والے احرام باندھنے سے لے کر حجر اسود کو بوسہ دینے تک تلبیہ کہیں گے۔\n۲۔ معتمر کے لیے طواف کعبہ بھی ضروری ہے۔"}],[834,"عبداللہ (بن مسعود رضی اللہ عنہ) سے مروی ہے کہ انہوں نے عمرہ میں بیت اللہ کا طواف کرنے کے بعد صفا پر تلبیہ کہا۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/44)، المعرفة السنن والآثار لہ (3001)۔","f":"۱۔ سیدنا جابر بن عبداللہ رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم جب صفا پہاڑی کے نزدیک پہنچے تو یہ آیت تلاوت فرمائی ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ﴾ (البقرہ: ۱۵۸) پھر کہا ہم وہیں سے شروع کرتے ہیں جس کا ذکر اللہ نے پہلے کیا ہے۔ پھر صفا پر چڑھے یہاں تک کہ بیت اللہ کو دیکھ کر اللہ کی کبریائی اور وحدانیت بیان فرمائی۔ اور پھر ’’لا اله الا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير، لا اله الا الله وحده انجز وعده ونصر عبده وهزم الاحزاب وحده‘‘ پڑھا اور پھر اس کے درمیان دعا کی اور اس طرح تین بار (مذکورہ کلمات کہے.... الخ۔ (صحیح مسلم، کتاب الحج، باب حجة النبی صلی اللہ علیہ وسلم، رقم: ۱۲۱۸)\n۲۔ صفا و مروہ کی سعی حج وعمرہ کا رکن ہے۔"}],[835,"نافع رحمہ اللہ سے مروی ہے کہ عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے وہ فرماتے تھے، ’’ما استیسر من الھدی‘‘ سے مراد اونٹ اور گائے کی قربانی ہے۔ (1)","",{"k":"(1) اسنادة صحیح: مالک فی المؤطا (5/24)، المعرفة السنن والآثار لہ (2742)، ابن ابی شیبة (12778، 12781، 12788)۔","f":"۱۔ ارشاد باری تعالیٰ ہے: ﴿فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ﴾ (البقرہ: ۱۹۴) ’’یعنی جو شخص عمرہ کے ساتھ حج کا تمتع کرلے۔ اسے جو قربانی میسر ہو کر ڈالے۔‘‘\n۲۔ حج تمتع اور قرآن میں ایک ہدی (ایک بکری یا پھر اونٹ یا گائے کے ساتویں حصے) کی قربانی دینی ضروری ہے۔\n۳۔ ابن عمر رضی اللہ عنہما نے فرمانِ الہی کی تفسیر گائے یا اونٹ کی قربانی سے کی ہے۔\n۴۔ قربانی کی سب سے افضل قسم اونٹ پھر گائے اور پھر بکری ہے۔ تاہم قربانی کرنے والے کی استطاعت پر منحصر ہے اگر اس کی استطاعت بکری کی قربانی کی ہے تو اس قربانی سے بھی اس کا فریضہ ادا ہو جائے گا۔\n۵۔ حج کے موقع پر قربانی کے لیے جانوروں میں بھی وہ تمام خصوصیات اور شرائط و قیود ملحوظ رکھی جائیں گی جن کا عید قربان کے موقع پر خیال رکھا جاتا ہے۔\n۶۔ اگر حج تمتع کرنے والا قربانی نہ کر سکے تو وہ بطور فدیہ دس روزے رکھے گا۔ (دیکھئے تفصیل کے لیے فوائد حدیث نمبر: ۸۰۸)"}],[836,"ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (کوہان کی) دائیں جانب اشعار کیا۔ (1)","",{"k":"(1) مسلم (1243)۔","f":"۱۔ اونٹ کی کوہان کی ایک طرف اتنا زخم کیا جائے کہ خون بہہ نکلے شعار کہلاتا ہے۔\n۲۔ قربانی کے جانوروں کو اشعار کرنا مشروع ہے۔\n۳۔ اشعار اس بات کی علامت ہوتا ہے کہ یہ جانور ہدی کا ہے۔\n۴۔ قربانی کے جانوروں کو اشعار کرنے کے ساتھ ساتھ ان کے گلے میں قلادہ (پٹہ) ڈالنا بھی مستحب ہے۔ (دیکھئے: صحیح بخاری، رقم: ۱۶۹۴)\n۵۔ ہدی اس جانور کو کہا جاتا ہے جسے قربانی کی غرض سے حرم کی حدود میں ذبح کیا جاتا ہے۔\n۶۔ حاجی حضرات کے علاوہ عام مسلمان بھی ہدی کے جانور کو مکہ بھیج سکتا ہے۔ (دیکھئے: صحیح بخاری، رقم: ۱۷۰۲، ۱۷۰۳، ۱۶۹۶)"}],[837,"نافع رحمہ اللہ سے روایت ہے کہ ابن عمر رضی اللہ عنہما سے مروی ہے کہ وہ کچھ حرج نہیں سمجھتے تھے کہ (اونٹ کی) بائیں جانب اشعار کیا جائے یا دائیں جانب۔ (1)","",{"k":"(1) اسنادة ضعیف لضعف مسلم بن خالد ولعنعنة ابن جریج: البیہقی (5/232)، المعرفة السنن والآثار لہ (3281)۔"}],[838,"ابن عمر رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم سے پوچھا کہ محرم کیسے کپڑے پہنے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قمیص، شلوار میں، پگڑیاں، ٹوپیاں اور موزے محرم نہ پہنے۔ اور اگر کسی کے پاس جوتے نہ ہوں تو وہ موزوں کو ٹخنوں تک کاٹ کر پہن لے۔‘‘ (1)","",{"k":"(1) البخاری (1532)، مسلم (1177)۔"}],[839,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے دریافت کیا کہ محرم کیسے کپڑے پہنے؟ آپ صلی اللہ علیہ وسلم نے اسے کہا، وہ (محرم) نہ قمیص پہنے، نہ پگڑی، نہ ٹوپی، نہ شلوار اور نہ ہی موزے پہنے مگر جس کے پاس جوتے نہیں تو وہ موزوں کو ٹخنوں سے نیچے تک کاٹ کر پہن لے۔ (1)","",{"k":"(1) البخاری (134)، مسلم (1177)۔","f":"۱۔ معلوم ہوا دورانِ احرام ایسے کپڑے کا استعمال ممنوع ہے جسے سلائی کر کے جسم کے مطابق بنایا جائے مثلاً: شلوار قمیص، بنیان وغیرہ۔\n۲۔ پگڑی اگرچہ سلا ہوا کپڑا نہیں تاہم اس کا استعمال بھی جائز نہیں اسی طرح ٹوپی پہننا بھی درست نہیں۔\n۳۔ برنس: ہر وہ کپڑا جس میں ٹوپی لگی ہو جیسے برساتی کوٹ وغیرہ بعض کے نزدیک اس سے مراد لمبی ٹوپی ہے جسے شروع زمانہ اسلام میں لوگ پہنا کرتے تھے۔ (لغات الحدیث: ۱/ ۱۳۷)"}],[840,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ محرم زعفران یا ورس سے رنگا ہوا کپڑا پہنے۔ فرمایا: ’’جس کے پاس جوتے نہیں تو وہ موزوں کو ٹخنوں سے نیچے تک کاٹ کر پہن لے۔‘‘ (1)","",{"k":"(1) البخاری (5852)، مسلم (1177)۔","f":"۱۔ ورس ایک قسم کی زرد رنگ کی گھاس ہے جس سے کپڑے رنگتے ہیں۔ (لغات الحدیث: ۴/ ۲۷۵)۔\n۲۔ زعفران اور ورس سے رنگے ہوئے کپڑوں میں چونکہ خوشبو پیدا ہو جاتی ہے اس لیے نبی صلی اللہ علیہ وسلم نے محرم کے لیے ایسے کپڑوں کا استعمال ممنوع قرار دیا ہے۔"}],[841,"عبداللہ بن عباس رضی اللہ عنہما بیان فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا آپ خطبہ دیتے ہوئے فرما رہے تھے: ’’جب محرم کے پاس جوتے نہ ہوں تو وہ موزے پہن لے اور جب وہ تہبند نہ پائے تو شلوار پہن لے۔‘‘ (1)","",{"k":"(1) البخاری (1740)، مسلم (1178)۔","f":"۱۔ مذکورہ حدیث میں نبی صلی اللہ علیہ وسلم نے محرم کو ٹخنوں کے نیچے تک کاٹے بغیر موزوں کے استعمال اور ازار بند کی عدم موجودگی میں شلوار کے پہننے کی اجازت دی ہے جبکہ سابقہ روایات میں شلوار پہننے کی ممانعت اور جوتے کی عدم موجودگی میں موزوں کے استعمال اور پھر انہیں ٹخنوں کے نیچے تک کاٹ دینے کا حکم دیا گیا ہے۔ تو اس سلسلہ میں شیخ الاسلام ابن تیمیہ رحمہ اللہ فرماتے ہیں پہلے کاٹنے کا حکم تھا مگر بعد میں آپ صلی اللہ علیہ وسلم نے میدان عرفات میں خطبہ ارشاد فرماتے ہوئے نہ کاٹنے کی بھی رخصت فرما دی۔ اور اہل علم کے اس سلسلہ میں وارد دو اقوال میں سے صحیح تر قول یہی رخصت والا ہے۔ (بحوالہ مناسک الحج والعمرة للالبانی: ۱۲ ص حاشیہ)\n۲۔ مذکورہ حدیث میں نبی صلی اللہ علیہ وسلم نے تہبند کے قائم مقام چادر نہ ملنے کی صورت میں شلوار پہن لینے کی بھی رخصت فرما دی ہے۔"}],[842,"ابن جریج سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا کہ اس نے رنگدار رسی سے احرام باندھا ہوا ہے آپ صلی اللہ علیہ وسلم نے دو دفعہ فرمایا، رسی اتار دو، رسی اتار دو۔ (1)","",{"k":"(1) اسنادة ضعیف لإرسالہ: البیہقی (5/51)، المعرفة السنن والآثار لہ (2836)۔"}],[843,"مسلم بن جندب سے روایت ہے وہ بیان کرتے ہیں کہ ایک آدمی آیا وہ ابن عمر رضی اللہ عنہما سے سوال کر رہا تھا جبکہ میں ان کے ساتھ تھا۔ اس آدمی نے کہا: احرام کی حالت میں، میں اپنی چادر کی دونوں طرفوں کو مخالف سمت میں پیچھے کی طرف لے جا کر ان پر گانٹھ لگا دوں۔ تو عبداللہ بن عمر رضی اللہ عنہما نے فرمایا: تو بالکل گانٹھ نہ لگا۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی (5/51)، المعرفة السنن والآثار لہ (2835)، ابن ابی شیبة (15438)۔","f":"۱۔ مردوں کے لیے دو چادروں میں احرام مشروع ہے، جن میں سے ایک چادر بطور تہبند جبکہ دوسری اوپر کے لیے ہوگی۔\n۲۔ بہتر یہ ہے کہ احرام کی چادر میں سفید ہوں۔\n۳۔ عورتیں معمول کے کپڑے پہنیں گی۔\n۴۔ معلوم ہوا احرام کی چادروں کی عام حالات میں گرہ لگانی درست نہیں۔ البتہ بوقت ضرورت گرہ لگائی جاسکتی ہے۔ (واللہ اعلم)"}],[844,"نافع نے بیان کیا کہ ابن عمر رضی اللہ عنہما نے جوان پر کپڑا اتھا اس کی گانٹھ نہیں لگائی، بلکہ اس کے دونوں کناروں کو موڑ کر اپنے ازار کے اندر کر لیا۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی (5/81)، المعرفة السنن والآثار لہ (2834)۔"}],[845,"طاوس سے روایت ہے بیان کرتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کو بیت اللہ کا طواف کرتے ہوئے دیکھا، کہ انہوں نے (احرام کو) ایک کپڑے کے ساتھ اپنے پیٹ پر باندھ ہوا ہے۔ (1)","",{"k":"(1) اسنادة ضعیف لضعف ہشام بن حجیرة ولعنعنة ابن جریج: البیہقی (5/51)، المعرفة السنن والآثار لہ (2833)۔","f":"معلوم ہوا ابن عمر رضی اللہ عنہما احرام کی اوپر والی چادر کو ازار بند کے اندر موڑ دیتے۔ انہیں گرہ نہیں لگاتے تھے۔"}],[846,"ابو جعفر سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے عبداللہ بن جعفر پر احرام کی حالت میں دو رنگے ہوئے کپڑے دیکھے تو پوچھا یہ کپڑے کیسے ہیں؟ علی بن ابوطالب رضی اللہ عنہ نے فرمایا: میں (کسی کی ضرورت) نہیں سمجھتا کہ وہ ہمیں سنت سکھائے، اس پر عمر رضی اللہ عنہ خاموش ہو گئے۔ (1)","",{"k":"(1) اسنادة ضعیف لإنقطاعہ فان ابا جعفر لم یدرک عمر بن الخطاب وعلی بن ابی طالب: البیہقی (5/59)، المعرفة السنن والآثار لہ (2858)۔"}],[847,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع کیا کہ کوئی آدمی زعفران کا استعمال کرے۔ (1)","",{"k":"(1) البخاری (5846)، مسلم (2101)۔","f":"۱۔ معلوم ہوا مردوں کے لیے زعفرانی کا استعمال ممنوع ہے۔\n۲۔ تھوڑے بہت زرد رنگ کا استعمال درست ہے جیسا کہ عبدالرحمن بن عوف رضی اللہ عنہ پر نبی صلی اللہ علیہ وسلم نے زردی کے نشانات دیکھے اور سکوت فرمایا۔ (دیکھئے! صحیح بخاری، رقم: ۵۱۵۳، صحیح مسلم، رقم: ۸۱/ ۱۴۲۷)\n۳۔ البتہ مردوں کے لیے زرد رنگ کے کپڑوں کا استعمال درست نہیں جیسا کہ سیدنا علی بن ابی طالب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ریشمی کپڑے، زرد رنگ سے رنگے ہوئے کپڑے، سونے کی انگوٹھی اور حالت رکوع میں قرآن پڑھنے سے منع فرمایا۔ (صحیح مسلم، کتاب اللباس والزینة، باب النھی عن لبس الرجل الثوب المعصفر، رقم: ۲۰۷۸)"}],[848,"نافع رحمہ اللہ سے روایت ہے کہ ابن عمر رضی اللہ عنہما محرم کے لیے پیٹی پہننا ناپسند کرتے تھے۔ (1)","",{"k":"(1) اسنادة صحیح: مالک فی الموطأ (2897)۔","f":"۱۔ منطق: نطاق کو کہتے ہیں اور اس کی جمع مناطق ہے اور اس سے مراد کمر بند ہے۔\n۲۔ معلوم ہوا ابن عمر رضی اللہ عنہما محرم کے لیے کمر بند کا استعمال مکروہ جانتے تھے۔\n۳۔ سعید بن مسیب رحمہ اللہ فرماتے ہیں اگر محرم کپڑوں کے نیچے پیٹی کمر بند باندھ لے تو کچھ حرج نہیں جبکہ اس کے دو کناروں میں تھمے ہوں اور وہ باندھ دیے جائیں۔ (یعنی کھلے نہ چھوڑے جائیں)۔ (موطا امام مالک، کتاب الحج، باب لبس المحرم المنطقة) امام مالک رحمہ اللہ ان دونوں باتوں کو نقل کرنے کے بعد فرماتے ہیں اس مسئلہ میں سعید بن مسیب رحمہ اللہ سے مروی بات راجح ہے۔ واللہ اعلم"}],[849,"یعلی بن امیہ رضی اللہ عنہ سے روایت ہے بیان فرماتے ہیں ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جعرانہ میں تھے تو آپ کے پاس ایک آدمی آیا اس نے جبہ پہنا ہوا تھا اور وہ خلوق میں بسا ہوا تھا۔ اس نے کہا، اے اللہ کے رسول (صلی اللہ علیہ وسلم)! میں نے عمرہ کے لیے احرام باندھا ہے اور میرے اوپر یہ (جبہ) ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ’’تو اپنے حج کی ادائیگی میں اس کا کیا کرتا؟’’اس آدمی نے کہا، میں اس جبہ کو اتار دیتا اور اس خلوق کو دھو لیتا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘جس طرح تو اپنے حج میں کرنے والا ہے اسی طرح تو اپنے عمرہ میں بھی کی۔‘‘ (یعنی جبہ اتار کر خلوق کے اثر کو زائل کر دو۔) (1)","",{"k":"(1) البخاری (1789)، مسلم (1180)۔"}],[850,"یعلی بن امیہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے پاس ایک اعرابی آیا اور اس پر قمیص تھی یا جبہ تھا اور اس پر زردی کے نشانات تھے۔ اس نے کہا میں نے احرام باندھا ہے اور میرے اوپر یہ (جبہ یا قمیص) ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنی قمیص یا اپنے جبے کو اتار دو اور اس زردی کو اپنے آپ سے صاف کر دو۔ اور جس طرح تم حج میں کرتے ہو اسی طرح اپنے عمرہ میں بھی کرو۔ (1)","",{"k":"(1) البخاری (1536)، مسلم (1180)۔","f":"۱۔ جعرانہ مقام پر نبی صلی اللہ علیہ وسلم نے غزوہ حنین کا مال غنیمت تقسیم فرمایا تھا، اور مذکورہ حدیث میں موجود واقعہ اسی وقت کا ہے۔\n۲۔ مردوں کے لیے احرام کی دو چادریں ہیں سلے ہوئے کپڑوں میں احرام نہیں ہے۔\n۳۔ زعفران اور زرد رنگ کی خوشبو کا استعمال مردوں کے لیے عام حالات میں بھی درست نہیں تو حالت احرام میں بالا ولی اس کا استعمال ممنوع ہے۔\n۴۔ محرم آدمی حالت احرام میں خوشبو نہیں لگا سکتا البتہ احرام باندھنے سے قبل خوشبو کا استعمال مسنون ہے اگر چہ اس کا اثر بعد میں بھی باقی رہے۔\n۵۔ حج و عمرہ کے احترام کے احکامات ایک جیسے ہیں۔"}],[851,"ابوہریرہ رضی اللہ عنہ سے روایت ہے انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا آپ نے فرمایا: ’’جو عورت اللہ اور آخرت کے دن پر ایمان رکھتی ہو اس کے لیے جائز نہیں کہ وہ ایک دن رات کا سفر بغیر کسی محرم کے کرے۔‘‘ (1)","",{"k":"(1) البخاری (1088)، مسلم (1399)۔","f":"۱۔ معلوم ہوا عورت محرم کے بغیر ایک دن رات کا سفر بھی نہیں کرسکتی خواہ وہ حج و عمرہ جیسا مبارک سفر ہی کیوں نہ ہو۔\n۲۔ ٹریول ایجنٹس کا حج و عمرہ کے سفر کے لیے غیر مردوں کو عورتوں کا کاغذات میں محرم ظاہر کرنا خلاف شرع ہے اور اس طرح کاروبار کرنا کسی صورت جائز نہیں۔\n۳۔ محرم سے مراد وہ رشتہ دار مرد ہیں جن سے عورت کا ہمیشہ کے لیے نکاح حرام ہے۔\n۴۔ وقتی محرم والا نظریہ باطل ہے۔\n۵۔ اگر کسی عورت کو محرم میسر نہیں تو اس پر حج فرض نہیں کیونکہ وہ حج کے لیے استطاعت نہیں رکھتی۔\n۶۔ اللہ اور آخرت پر ایمان کا تقاضا ہے کہ حالات کیسے بھی ہوں مسلمان اپنے آپ کو شریعت کا پابند بنائے اور کسی بھی حیل و حجت سے کام نہ لے۔\n۷۔ عورت کے لیے دورانِ سفر محرم کی پابندی کا مقصد اس کی عزت و عصمت کی حفاظت ہے۔"}],[852,"ابن عباس رضی اللہ عنہما سے روایت ہے بیان فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک خطبہ میں ارشاد فرماتے سنا کہ کوئی مرد کسی عورت کے ساتھ خلوت اختیار نہ کرے، اور کسی عورت کے لیے جائز نہیں کہ وہ اپنے محرم رشتہ دار کے بغیر سفر کرے۔ ایک آدمی کھڑا ہو گیا اور اس نے کہا اے اللہ کے رسول (صلی اللہ علیہ وسلم)! میرا نام فلاں فلاں غزوہ میں لکھ دیا گیا جبکہ میری بیوی حج کے لیے چلی گئی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جاؤ تم بھی اپنی بیوی کے ساتھ حج کرو۔‘‘ (1)","",{"k":"(1) البخاری (1862)، مسلم (1341)۔","f":"۱۔ سفر میں محرم کی موجودگی اس قدر اہم ہے کہ اس عذر کی وجہ سے نبی صلی اللہ علیہ وسلم نے صحابی کو جہاد پر جانے کی بجائے اپنی بیوی کے ساتھ حج ادا کرنے کا حکم دیا۔\n۲۔ مرد کا کسی غیر محرم عورت کے ساتھ خلوت اختیار کرنا جائز نہیں کیونکہ یہ چیز فتنے کا باعث ہے۔\n۳۔ مجاہدین کے ناموں کو لکھنا اور افواج کا ریکارڈ قائم کرنا درست ہے۔\n۴۔ اگر کسی مجاہد یا فوجی کا نام میدانِ جنگ کے لیے جانے والوں کی فہرست میں شامل ہو تو اسے شرعی عذر کی بنا پر واپس گھر بھیجنا جائز ہے۔"}],[853,"جعفر بن محمد اپنے باپ سے روایت ہے کہ انہوں نے کہا ہمیں حدیث بیان کی جابر رضی اللہ عنہ نے اور وہ نبی صلی اللہ علیہ وسلم کے حج (حجة الوداع) کے متعلق بیان کر رہے تھے۔ فرمایا: جب ہم ذوالحلیفہ مقام پر پہنچے تو اسماء بنت عمیس رضی اللہ عنہا نے بچہ جنا، نبی صلی اللہ علیہ وسلم نے اسے غسل کر کے احرام باندھنے کا حکم دیا۔ (1)","",{"k":"(1) مسلم (1210)۔","f":"۱۔ حیض و نفاس حج کی ادائیگی سے مانع نہیں۔\n۲۔ حیض و نفاس والی عورتیں بھی غسل کر کے میقات سے احرام باندھیں گی۔\n۳۔ سفر حج میں اگر عورت کے ہاں بچے کی پیدائش ہو تو اسے نفاس کے ختم ہونے کا انتظار کیے بغیر سفر شروع کر دینا چاہیے۔\n۴۔ نفاس والی عورت کو ایک کپڑا لنگوٹ کی طرح بھی باندھ لینا چاہیے تاکہ دوسرے کپڑے خون سے محفوظ رہیں۔ (سنن ابن ماجہ، رقم: ۲۹۱۳)\n۵۔ حیض و نفاس کے ایام میں چونکہ عورتیں نماز نہیں پڑھ سکتیں، مسجد نہیں آسکتیں، اس لیے وہ بیت اللہ کا طواف بھی نہیں کریں گی۔\n۶۔ طواف کعبہ کے علاوہ ذکر و اذکار اور تلبیہ ایسی عورتیں بھی پڑھیں گی۔\n۷۔ اس حدیث سے معلوم ہوا حاملہ عورت بھی سفر حج پر روانہ ہو سکتی ہے۔\n۸۔ اسماء بنت عمیس رضی اللہ عنہا سیدنا ابوبکر صدیق رضی اللہ عنہ کی زوجہ محترمہ تھیں اس سفر میں ان کے ہاں محمد بن ابوبکر رضی اللہ عنہما کی ولادت ہوئی جو صغار صحابہ کرام رضی اللہ عنہم میں سے ہیں۔\n۹۔ ذوالحلیفہ اہل مدینہ کا میقات ہے۔"}],[854,"جابر رضی اللہ عنہ سے روایت ہے بیان فرماتے ہیں، عورت خوشبو والے کپڑے نہیں پہنے گی، اور وہ زرد رنگ والے کپڑے پہن لے، کیونکہ میرے خیال میں زرد رنگ خوشبو نہیں ہے۔ (1)","",{"k":"(1) اسنادة ضعیف، فان ابن جریج مدلس، وقد عنعن: البیہقی (5/59)، المعرفة السنن والآثار لہ (2859)، ابن ابی شیبة (12880)۔"}],[855,"ابن عباس رضی اللہ عنہما سے روایت ہے فرمایا، عورت بڑی چادر اوڑھے گی اور اس طرح نہیں کرے گی۔ عطاء کہتے ہیں میں نے پوچھا کیا نہیں کرے گی؟ تو انہوں نے مجھے اشارہ کر کے بتایا، جس طرح عورت اوڑھنی لیتی ہے۔ پھر جو اوڑھنی رخسار پر ہوتی ہے اس کا اشارہ کیا اور فرمایا اس سے اپنے چہرے کو نہیں چھپائے گی اور جو اضافی چادر ہوگی اس کو چہرے پر اسی طرح لٹکائے گی جس طرح کہ وہ لٹکی ہوتی ہے۔ نہ اس کو الٹے گی، نہ ڈالے گی، اور نہ اس کو ملائے گی۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی فی المعرفة السنن والآثار (2822)۔","f":"۱۔ حالت احرام میں عورتوں کو جس نقاب سے منع کیا گیا ہے اس کا تعلق حجاب یا چہرے کے پردے سے نہیں بلکہ وہ مخصوص نقاب ہے جسے عورتیں چہرے پر ناک یا آنکھوں کے نیچے باندھتی ہیں۔ جس سے ناک اور رخساروں کو چھپا لیا جاتا ہے جبکہ آنکھیں اور پیشانی کا کچھ حصہ نظر آتا ہے۔ ایسا نقاب احرام والی عورت کے لیے پہننا منع ہے۔ لیکن اگر چادر یا دوپٹے کو سر کے اوپر سے اس طرح لٹکایا جائے کہ وہ پردے کا کام دے تو یہ درست ہے۔\n۲۔ حالت احرام میں پردے کا اہتمام ضروری ہے جیسا کہ سیدہ فاطمہ بنت منذر رضی اللہ عنہا بیان فرماتی ہیں: ’’کنا نخمر وجوھنا ونحن محرمات ونحن مع اسماء بنت ابی بکر الصدیق فلا تنکرة علینا’’‘‘کہ ہم احرام کی حالت میں اپنے چہرے ڈھانپا کرتیں اور اسماء بنت ابی بکر رضی اللہ عنہا بھی ہمارے ساتھ ہوتیں۔‘‘ (موطا امام مالک، کتاب الحج، باب تخمیر المحرم وجھہ: ۱/ ۳۲۸)۔\n۳۔ اکثر خواتین احرام کی حالت میں پردے کے اہتمام پر کوئی توجہ نہیں دیتیں اور اپنے پرائے محرم و غیر محرم کسی سے بھی پردہ نہیں کرتیں۔ حالانکہ ایسا کرنا عورتوں کے لیے عام حالات میں بھی درست نہیں کیونکہ ان کا یہ فعل اسلام کے مزاج سے قطعاً مناسبت نہیں رکھتا۔\n۴۔ عورتوں میں اس سستی کا باعث وہ روایات ہیں جن میں نقاب باندھنے سے منع کیا گیا ہے حالانکہ وہ ایک مخصوص نقاب ہے جیسا کہ اوپر وضاحت ہو چکی ہے نقاب ڈالنے یا لٹکانے اور پردہ سے کسی بھی حدیث میں منع نہیں کیا گیا۔ واللہ اعلم۔"}],[856,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ وہ عورتوں کو فتویٰ دیتے کہ وہ احرام میں اپنے موزوں کو کاٹ دیں۔ یہاں تک کہ صفیہ رضی اللہ عنہا نے انہیں عائشہ رضی اللہ عنہا کے واسطے سے بتایا کہ وہ عورتوں کو فتویٰ دیتی تھیں کہ وہ موزے نہ کاٹیں۔ اس کے بعد ابن عمر رضی اللہ عنہما نے اپنے فتویٰ کو ترک کر دیا۔ (1)","",{"k":"(1) البیہقی (5/52)، المعرفة السنن والآثار لہ (2839)، احمد (2/29)، وصححہ ابن خزیمة (2686)۔","f":"۱۔ نبی صلی اللہ علیہ وسلم نے شروع میں یہی حکم دیا تھا کہ جس کے پاس جوتا نہ ہو وہ موزے پہن لے البتہ انہیں ٹخنوں کے نیچے تک کاٹ لے لیکن بعد میں میدانِ عرفات میں موزے پہننے کی رخصت دی اور انہیں کاٹنے کا حکم بھی نہیں دیا۔ جیسا کہ پیچھے گزر چکا ہے دیکھئے: فوائد حدیث نمبر: ۸۴۱۔\n۲۔ مسائل میں علماء کے درمیان اختلاف ممکن ہے لیکن اختلاف برائے اختلاف اور اپنی بات پر بلا دلیل ڈٹ جانا کسی طور بھی مستحسن نہیں ہے۔\n۳۔ صحابہ کرام رضی اللہ عنہم ایک دوسرے کی آراء کا احترام کرتے اور حق کو بلا تامل قبول فرما لیتے۔\n۴۔ حق کی طرف رجوع اور اسے قبول کرنا اہل حق ہونے کی دلیل ہے۔"}],[857,"صفیہ بنت شیبہ سے روایت ہے بیان فرماتی ہیں کہ میں عائشہ رضی اللہ عنہا کے پاس تھی جب بنی عبدالدار کی عورتوں میں سے ایک عورت آئی جسے تملک کہا جاتا تھا۔ اس نے کہا اے ام المومنین! میری فلاں بیٹی نے قسم اٹھائی ہے کہ وہ موسم (حج) میں اپنے زیورات نہیں پہنے گی۔ تو عائشہ رضی اللہ عنہا نے فرمایا: اس سے کہو کہ مومنوں کی ماں تجھے قسم دے کر کہتی ہے کہ تو اپنے سارے زیورات پہن لے۔ (1)","",{"k":"(1) اسنادة حسن: البیہقی (5/52)، المعرفة السنن والآثار لہ (2840)۔","f":"۱۔ حالت احرام میں مرد کے لیے چاندی کی انگوٹھی پہننا عورت کا زیورات استعمال کرنا، گھڑی باندھنا، عینک لگانا وغیرہ سبھی امور جائز ہیں ان میں سے کسی کی بھی ممانعت ثابت نہیں۔\n۲۔ سیدہ عائشہ رضی اللہ عنہا سے صحیح بخاری میں تعلیقاً مروی ہے کہ وہ احرام والی عورت کے لیے زیورات کے استعمال، سیاہ یا گلابی کپڑوں کے استعمال اور موزوں کے پہننے میں کوئی مضائقہ نہیں سمجھتی تھیں۔ (صحیح بخاری، کتاب الحج، باب ما یلبس المحرم من الثیاب والاردیة والازر)"}],[858,"عبداللہ بن عامر بن ربیعہ نے کہا کہ میں عمر رضی اللہ عنہ کا ساتھی بنا تو میں نے ان کو حج کے دوران خیمہ استعمال کرتے ہوئے نہیں دیکھا حتی کہ وہ واپس تشریف لے آئے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/70)، المعرفة السنن والآثار لہ (2899)، ابن ابی شیبة (14254)۔","f":"۱۔ مذکورہ روایت میں ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے حج کے موقع پر خیمہ استعمال نہیں کیا۔ جبکہ صحیح احادیث سے نبی صلی اللہ علیہ وسلم کا خیمہ لگوانا اور حالت احرام میں حجة الوداع کے موقع پر صحابہ کا آپ پر سایہ کرنا ثابت ہے۔ سیدنا جابر رضی اللہ عنہ سے مروی طویل حدیث جس میں وہ نبی صلی اللہ علیہ وسلم کے حج کا آنکھوں دیکھا حال بیان فرماتے ہیں، میں ہے: وامر بقبة من شعر تضرب لہ بنمرة ...... حتی اتی عرفة فوجد القبة قد ضربت لہ بنمرة فنزل بھا حتی اذا زاغت الشمس ... الخ۔ آپ صلی اللہ علیہ وسلم نے وادی نمرہ میں خیمہ نصب کرنے کا حکم فرمایا: جب حکم آپ عرفات کے لیے روانہ ہوئے تو وادی نمرہ میں اپنے لیے خیمہ نصب پایا، آپ صلی اللہ علیہ وسلم اس (خیمہ) میں تشریف لے گئے یہاں تک کہ سورج ڈھل گیا۔ (صحیح مسلم، کتاب الحج، باب حجة النبی، رقم: ۱۲۱۸) اسی طرح ام حصین رضی اللہ عنہا بیان فرماتی ہیں میں نے اسامہ اور بلال رضی اللہ عنہما کو دیکھا ان میں سے ایک نے نبی صلی اللہ علیہ وسلم کی اونٹنی کی نکیل پکڑی ہوئی تھی اور دوسرے نے اپنے کپڑے سے آپ کو دھوپ سے بچانے کے لیے سایہ کیا ہوا تھا، اور یہ سلسلہ جمرہ عقبہ کو رمی کرنے تک رہا۔ (مسلم، کتاب الحج، باب استحباب رمی الجمرة العقبة ... الخ، رقم: ۱۲۹۸)\n۲۔ مذکورہ حدیث کے راوی عبداللہ بن عامر سے ان کے شاگرد یحیی بن سعید نے دریافت کیا (جب عمر رضی اللہ عنہ نے خیمہ نہیں لگایا) تو وہ سایہ کس طرح حاصل کرتے تو انہوں نے جواباً کہا: وہ درخت پر چمڑے کا چادر نما ٹکڑا ڈال کر سایہ حاصل کرتے تھے۔ (مصنف ابن ابی شیبہ، کتاب الحج، باب فی المحرم یستظل، رقم: ۱۴۲۵۴)\n۳۔ مذکورہ دلائل سے معلوم ہوا محرم کے لیے دھوپ کی شدت سے بچنے کے لیے چھتری، کپڑے، خیمے وغیرہ کسی بھی چیز کے سائے میں بیٹھنا درست ہے۔"}],[859,"عبداللہ بن ابی بکر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ عمرہ قضا میں تلواریں لٹکائے ہوئے آئے اور وہ احرام میں تھے۔ (1)","",{"k":"(1) اسنادة ضعیف جدا، لضعف شیخ الشافعی والإعضالہ: البیہقی فی المعرفة السنن والآثار (2748)۔","f":"۱۔ مذکورہ روایت اگر چہ ضعیف ہے تاہم مسئلہ صحیح ہے کہ محرم کے لیے اپنے ساتھ اسلحہ، ہتھیار رکھنا جائز ہے جیسا کہ سیدنا براء بن عازب رضی اللہ عنہ صلح حدیبیہ کی روداد بیان کرتے ہوئے فرماتے ہیں: ’’وصالحھم علی ان یدخل ھو واصحابہ ثلاثة ایام ولا یدخلوھا الا بجلبان الصلاح۔’’‘‘کہ رسول اللہ صلی اللہ علیہ وسلم نے ان (مشرکین) کے ساتھ اس بات پر صلح کی تھی کہ نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ (رضی اللہ عنہم) تین دن کے لیے (آئندہ سال) آئیں گے اور مکہ میں اس حال میں داخل ہوں گے کہ ان کے ہتھیار ان کے میانوں میں ہوں گے۔’’(صحیح بخاری، کتاب الصلح، باب کیف یکتب ھذا ما صالح ...... الخ، رقم: ۲۶۹۸، صحیح مسلم، رقم: ۱۷۸۳) امام ابو داؤد رحمہ اللہ نے اس مذکورہ بالا حدیث پر‘‘باب المحرم یحمل السلاح‘‘ کہ محرم ہتھیار بند ہو سکتا ہے کے عنوان سے باب قائم کیا ہے۔ (سنن ابی داؤد، کتاب الحج، قبل الحدیث رقم: ۱۸۳۲)"}],[860,"عبداللہ بن حنین سے روایت ہے کہ عبداللہ بن عباس اور مسور بن مخرمہ رضی اللہ عنہما کا مقام ابواء میں اختلاف ہوا۔ ابن عباس رضی اللہ عنہما نے کہا، محرم اپنا سر دھو سکتا ہے۔ اور مسور رضی اللہ عنہ نے کہا، محرم اپنا سر نہیں دھو سکتا۔ تو عبداللہ بن عباس رضی اللہ عنہما نے مجھے ابوایوب رضی اللہ عنہ کے پاس (مسئلہ پوچھنے کے لیے) بھیجا۔ میں پہنچا تو وہ کنویں کی دو لکڑیوں کے بیچ غسل کر رہے تھے، ایک کپڑے سے انہوں نے پردہ کر رکھا تھا۔ میں نے پہنچ کر سلام کیا تو انہوں نے پوچھا کون ہو؟ میں نے کہا میں عبداللہ ہوں اور مجھے ابن عباس رضی اللہ عنہما نے آپ کی طرف بھیجا ہے کہ آپ سے دریافت کروں کہ احرام کی حالت میں رسول اللہ صلی اللہ علیہ وسلم سر مبارک کس طرح دھوتے تھے۔ فرمایا، (یہ سن کر) اپنے ہاتھ کپڑے پر (جس سے پردہ کیا ہوا تھا) رکھ کر اسے نیچے کیا حتی کہ مجھے آپ کا سر نظر آیا، پھر جو شخص ان کے بدن پر پانی ڈال رہا تھا۔ اس سے انہوں نے پانی ڈالنے کے لیے کہا۔ اس نے ان کے سر پر پانی ڈالا، پھر انہوں نے سر کو اپنے دونوں ہاتھوں سے دھویا اور دونوں ہاتھ آگے لے گئے پھر پیچھے لائے پھر فرمایا میں نے رسول اللہ صلی اللہ علیہ وسلم کو (حالت احرام میں) اسی طرح کرتے دیکھا۔ (1)","",{"k":"(1) البخاری (1840)، مسلم (1205)۔","f":"۱۔ معلوم ہوا محرم نہا سکتا ہے اور سر بھی دھو سکتا ہے خواہ غسل فرض ہو یا راحت و نشاط کے حصول کے لیے ہو۔\n۲۔ لوگوں کے سامنے ننگے ہو کر بے پردہ نہانا ممنوع ہے البتہ با پردہ ہو کر نہانا جائز ہے۔\n۳۔ اگر نہاتے ہوئے فطری انداز میں بال گر جائیں یا ٹوٹ جائیں تو وہ بال کاٹنے کے حکم میں نہیں لہذا فدیہ واجب نہ ہوگا۔\n۴۔ نہانے میں دوسرے شخص سے مدد لی جا سکتی ہے۔\n۵۔ دوران غسل اور وضو بوقت ضرورت بات کرنا جائز ہے۔\n۶۔ مسائل میں اختلاف رائے مذموم نہیں لیکن غلطی واضح ہو جانے کے بعد اس پر اصرار انتہائی قبیح عمل ہے۔\n۷۔ مسائل کی تحقیق کے سلسلہ میں جید علماء کی طرف رجوع کرنا چاہیے۔\n۸۔ علماء کو چاہیے کہ لوگوں کو مسائل دلائل سے واضح کریں۔\n۹۔ اہل حق اختلاف میں قرآن وسنت سے راہنمائی لیتے ہیں۔\n۱۰۔ صحیح احادیث آ جانے پر قیاس و رائے کو ترک کر لینا اہل حق کا شیوہ ہے۔\n۱۱۔ اہل علم سے مسائل دریافت کرنے کے لیے دوسروں سے مدد لی جا سکتی ہے۔\n۱۲۔ صحابہ کرام رضی اللہ عنہم میں مسائل پر بحث مباحثہ ہوتا تھا اور وہ لوگ نص کی طرف رجوع کرتے اور اسے قبول فرما لیتے۔\n۱۳۔ صحابہ کرام رضی اللہ عنہم کے نزدیک خبر واحد حجت تھی اگر چہ وہ تابعی ہی سے مروی کیوں نہ ہوتی۔\n۱۴۔ سیدنا مسور بن مخرمہ رضی اللہ عنہ نے جب نبی صلی اللہ علیہ وسلم کے عمل کے متعلق سنا تو ابن عباس رضی اللہ عنہما سے فرمایا: ’’لا اماریک ابداً’’‘‘میں آپ کے ساتھ کبھی بھی جھگڑا نہیں کروں گا۔‘‘ (صحیح مسلم، رقم: ۱۲۰۵)"}],[861,"یعلی بن امیہ سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ ایک اونٹ کی اوٹ میں غسل کر رہے تھے اور میں نے ان پر ایک کپڑے سے پردہ کر رکھا تھا کہ عمر بن خطاب رضی اللہ عنہ نے فرمایا، اے یعلی! میں اپنے سر پر پانی ڈالوں۔ تو میں نے کہا امیر المومنین بہتر جانتے ہیں۔ پھر عمر بن خطاب رضی اللہ عنہ نے فرمایا: اللہ کی قسم پانی بالوں کو پراگندگی میں زیادہ کرتا ہے۔ پھر اللہ تعالیٰ کا نام لے کر اپنے سر پر پانی ڈالا۔ (1)","",{"k":"(1) اسنادة ضعیف لانقطاعة بین عطاء وعمر: البیہقی (5/63)، المعرفة السنن والآثار لہ (2867)۔"}],[862,"ابن عباس رضی اللہ عنہ سے روایت ہے فرمایا بعض دفعہ عمر بن خطاب رضی اللہ عنہ نے کہا، آؤ میں تجھے پانی میں غوطہ دوں تاکہ ہم دیکھیں کس کا سانس لمبا ہے اور ہم احرام کی حالت میں تھے۔ (1)","",{"k":"(1) اسنادة صحیح: البیہقی (5/63)، المعرفة السنن والآثار لہ (2869)، ابن ابی شیبة (12847)۔","f":"۱۔ محرم کے لیے پانی میں غسل کرنا، نہانا، غوطے لگانا سب جائز ہے۔\n۲۔ سیدنا ابن عباس رضی اللہ عنہ سے سیدنا عمر بن خطاب رضی اللہ عنہ کو ان کے فہم قرآن کی وجہ سے خاص لگاؤ تھا۔\n۳۔ غوطہ زنی اور تیراکی ممنوع نہیں ہے۔"}]])